const CONNECT_COLUMNS: Array<{
	heading: string;
	links: Array<{ label: string; description: string; href: string }>;
}> = [
	{
		heading: "AGENTS & MEMORY",
		links: [
			{
				label: "Claude Desktop",
				description: "Connect Claude Desktop and claude.ai via MCP",
				href: "/connect-from/claude/",
			},
			{
				label: "Claude Code",
				description: "Plug memory directly into the Claude CLI",
				href: "/connect-from/claude/",
			},
			{
				label: "ChatGPT",
				description: "Org-scoped memory through one MCP endpoint",
				href: "/connect-from/chatgpt/",
			},
			{
				label: "OpenClaw",
				description: "Shared entity memory across OpenClaw agents",
				href: "/connect-from/openclaw/",
			},
		],
	},
	{
		heading: "CHAT & API",
		links: [
			{
				label: "Slack",
				description: "Company context in Slack — connect data, run agents",
				href: "/for/slackbot/",
			},
			{
				label: "Web App",
				description: "Interact with your agents natively in the web console",
				href: "/platforms/web/",
			},
			{
				label: "REST API",
				description: "Query org memory & trigger actions from any app",
				href: "/sdks/rest-api/",
			},
			{
				label: "See all platforms",
				description: "Discord, WhatsApp, Teams, Google Chat…",
				href: "/platforms/",
			},
		],
	},
];

function ConnectMenu() {
	const [open, setOpen] = useState(false);
	const ref = useRef<HTMLDivElement>(null);

	useEffect(() => {
		if (!open) return;
		const onKey = (e: KeyboardEvent) => {
			if (e.key === "Escape") setOpen(false);
		};
		const onPointerDown = (e: PointerEvent) => {
			if (!ref.current?.contains(e.target as Node)) setOpen(false);
		};
		document.addEventListener("keydown", onKey);
		document.addEventListener("pointerdown", onPointerDown);
		return () => {
			document.removeEventListener("keydown", onKey);
			document.removeEventListener("pointerdown", onPointerDown);
		};
	}, [open]);

	return (
		<div
			class="lp-connect"
			onMouseEnter={() => setOpen(true)}
			onMouseLeave={() => setOpen(false)}
			ref={ref}
		>
			<button
				aria-expanded={open}
				aria-haspopup="true"
				onClick={() => setOpen(!open)}
				type="button"
			>
				connect <span class="car">▾</span>
			</button>
			{open && (
				<div class="lp-connect-panel">
					{CONNECT_COLUMNS.map((col) => (
						<div key={col.heading}>
							<div class="lp-connect-h">[ {col.heading} ]</div>
							{col.links.map((link) => (
								<a class="lp-connect-item" href={link.href} key={link.label}>
									<span class="t">
										<span class="m" /> {link.label}
									</span>
									<span class="d">{link.description}</span>
								</a>
							))}
						</div>
					))}
				</div>
			)}
		</div>
	);
}

function MobileMenu() {
	const [open, setOpen] = useState(false);
	const ref = useRef<HTMLDivElement>(null);
	const triggerRef = useRef<HTMLButtonElement>(null);

