			<div class="mx-auto flex h-16 w-[min(72rem,calc(100%-40px))] items-center gap-1 sm:gap-5">
				<a class="lp-brand" href="/">
					<PixelLobster animate />
					<span class="wm">lobu</span>
				</a>
				{LINKS.map((link) => (
					<a
						class="hidden shrink-0 whitespace-nowrap font-mono text-[12.5px] tracking-[0.02em] transition-colors hover:text-[color:var(--color-page-text)] md:inline"
						href={link.href}
						key={link.href}
						style={{ color: "var(--color-page-text-muted)" }}
					>
						{link.label}
					</a>
				))}
				<ConnectMenu />
				<GitHubStarButton stars={stars} />
				<a
					class="lp-btn lp-btn-primary ml-auto whitespace-nowrap sm:ml-0"
					href={getLobuLoginUrl()}
					style={{ height: "40px", padding: "0 16px" }}
				>
					Log in
				</a>
				<ThemeToggle />
				<MobileMenu />
			</div>
		</nav>
	);
}

