55	/** Mirrors the inline theme script in BaseLayout: writes the palette straight
56	 *  onto <html style> (wins over the cascade), flips data-theme, and persists
57	 *  the choice where Starlight's own toggle reads it. */
58	function applyTheme(mode: "light" | "dark", persist = true) {
59		const el = document.documentElement;
60		const vars = mode === "dark" ? dark : light;
61		for (const [k, v] of Object.entries(vars)) {
62			el.style.setProperty(k, v);
63		}
64		el.setAttribute("data-theme", mode);
65		if (persist) {
66			try {
67				localStorage.setItem("starlight-theme", mode);
68			} catch {
69				// private mode — theme still applies for this page view
70			}
71		}
72		el.style.colorScheme = mode;
73		for (const meta of document.querySelectorAll<HTMLMetaElement>(
74			'meta[name="theme-color"]',
75		)) {
76			meta.content =
77				mode === "dark"
78					? dark["--color-page-meta-theme"]
79					: light["--color-page-meta-theme"];
80		}
81		document.body.classList.add(`${mode}-mode`);
82		document.body.classList.remove(mode === "dark" ? "light-mode" : "dark-mode");
83	}
