85	function ThemeToggle() {
86		useEffect(() => {
87			const media = window.matchMedia("(prefers-color-scheme: dark)");
88			const syncAutomaticTheme = () => {
89				let preference: string | null = null;
90				try {
91					preference = localStorage.getItem("starlight-theme");
92				} catch {
93					// Treat unavailable storage like automatic mode.
94				}
95				if (!preference || preference === "auto") {
96					applyTheme(media.matches ? "dark" : "light", false);
97				}
98			};
99			media.addEventListener("change", syncAutomaticTheme);
100			return () => media.removeEventListener("change", syncAutomaticTheme);
101		}, []);
102	
103		const toggle = () => {
104			const current = document.documentElement.getAttribute("data-theme");
105			const next = current === "dark" ? "light" : "dark";
106			applyTheme(next);
107		};
108	
109		return (
110			<button
111				class="lp-theme-toggle inline-flex h-10 w-10 shrink-0 items-center justify-center border font-mono text-[15px] leading-none transition-colors hover:border-[color:var(--color-page-text-muted)]"
