1	import { Link, Outlet, useLocation, useNavigate } from "@tanstack/react-router";
2	import {
3		ListChecks,
4		Lock,
5		MessageSquare,
6		Settings as SettingsIcon,
7		Shield,
8		Sparkles,
9	} from "lucide-react";
10	import { type ComponentType, useEffect } from "react";
11	import {
12		AgentEditorForm,
13		type AgentSection,
14	} from "@/components/agents/agent-editor-form";
15	import { AgentWorkbenchHeaderSkeleton } from "@/components/agents/agent-loading-shells";
16	import { ProposalReviewShell } from "@/components/agents/proposal-review-shell";
17	import { useCurrentOrg } from "@/hooks/use-current-org";
18	import { useMembers } from "@/hooks/use-members";
19	import { useOrgContext } from "@/hooks/use-org-context";
20	import {
21		isAgentSkillsSubPage,
22		isAgentSkillsTab,
23	} from "@/lib/agent-chat-routes";
24	import { agentTabLink } from "@/lib/agent-tab-links";
25	import {
26		type AgentItem,
27		useAgents,
28		useResolvedPath,
29		useSystemAgentId,
30	} from "@/lib/api";
31	import { useAuthState } from "@/lib/auth-state";
32	import { cn } from "@/lib/utils";
33	
34	export type AgentTab = "chat" | "behaviors" | AgentSection;
35	
36	const AGENT_TABS: readonly AgentTab[] = [
37		"chat",
38		"behaviors",
39		"identity",
40		"skills",
41		"guardrails",
42		"permissions",
43		"settings",
44	];
45	
46	export function parseAgentTab(value: unknown): AgentTab | undefined {
47		return typeof value === "string" &&
48			(AGENT_TABS as readonly string[]).includes(value)
49			? (value as AgentTab)
50			: undefined;
51	}
52	
53	const TAB_META: {
54		tab: AgentTab;
55		label: string;
56		icon: ComponentType<{ className?: string }>;
57	}[] = [
58		{ tab: "chat", label: "Chat", icon: MessageSquare },
59		{ tab: "behaviors", label: "Behaviors", icon: ListChecks },
60		{ tab: "skills", label: "Skills", icon: Sparkles },
61		{ tab: "guardrails", label: "Guardrails", icon: Shield },
62		{ tab: "permissions", label: "Permissions", icon: Lock },
63		{ tab: "settings", label: "Settings", icon: SettingsIcon },
64	];
65	
66	
67	
68	function TabLink({
69		owner,
70		agentId,
71		tab,
72		label,
73		icon: Icon,
74		activeTab,
75	}: {
76		owner: string;
77		agentId: string;
78		tab: AgentTab;
79		label: string;
80		icon: ComponentType<{ className?: string }>;
81		activeTab: AgentTab;
82	}) {
83		const link = agentTabLink(owner, agentId, tab);
84		const active = activeTab === tab;
85		// Same density as Home's "New conversation" / "Configure" row — active tab
86		// brightens; no second-row underline strip.
87		return (
88			<Link
89				{...link}
90				className={cn(
91					"inline-flex shrink-0 items-center gap-1.5 rounded-md px-2 py-1 text-sm transition-colors",
92					active
93						? "font-semibold text-foreground"
94						: "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
95				)}
96			>
97				<Icon className="h-4 w-4 shrink-0" />
98				{label}
99			</Link>
100		);
101	}
102	
103	function AgentHeaderTabs({
104		owner,
105		agentId,
106		activeTab,
107	}: {
108		owner: string;
109		agentId: string;
110		activeTab: AgentTab;
111	}) {
112		// The Permissions tab reads/writes the org-scoped write-gate envelope; its
113		// endpoints require org settings admin. Hide it from regular members so they
114		// never land on a 403 error state (they'd have no way to load or save it).
115		const { orgContext } = useOrgContext();
116		const { isAdmin } = useMembers(orgContext.organizationId);
117		const tabs = isAdmin
118			? TAB_META
119			: TAB_META.filter(({ tab }) => tab !== "permissions");
120		return (
121			<>
122				{tabs.map(({ tab, label, icon }) => (
123					<TabLink
124						key={tab}
125						owner={owner}
126						agentId={agentId}
127						tab={tab}
128						label={label}
129						icon={icon}
130						activeTab={activeTab}
131					/>
132				))}
133			</>
134		);
135	}
136	
137	
138	
139	export function AgentsWorkbenchLayout({
140		owner,
141		agentId,
142	}: {
143		owner: string;
144		agentId: string;
145	}) {
146		const navigate = useNavigate();
147		const { pathname } = useLocation();
148		const { isAuthenticated } = useAuthState();
149		const { isMember } = useCurrentOrg();
150		const canManageWorkspace = isAuthenticated && isMember;
151		const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
152			enabled: canManageWorkspace,
153		});
154		useSystemAgentId({
155			enabled: canManageWorkspace,
156		});
157	
158		const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;
159		const agentNotFound =
160			!selectedAgent && !isAgentsLoading && canManageWorkspace;
161	
162		const chatPrefix = `/${owner}/agents/${agentId}/chat`;
163		const conversationsPrefix = `/${owner}/agents/${agentId}/conversations`;
164		const isAgentChat =
165			pathname === chatPrefix || pathname.startsWith(`${chatPrefix}/`);
166		// Inbound platform conversations (e.g. a Slack thread) live on their own
167		// /conversations/$id route with no dedicated tab. Surface them under Chat
168		// instead of letting the activeTab fallback default them to Watchers.
169		const isAgentConversation =
170			pathname === conversationsPrefix ||
171			pathname.startsWith(`${conversationsPrefix}/`);
172		const isChat = isAgentChat || isAgentConversation;
173		const agentBase = `/${owner}/agents/${agentId}`;
174		const isBehaviorsTab =
175			pathname === `${agentBase}/behaviors` ||
176			pathname.startsWith(`${agentBase}/behaviors/`);
177		const isIdentityTab =
178			pathname === `${agentBase}/identity` ||
179			pathname === `${agentBase}/identity/`;
180		const isSettingsTab =
181			pathname === `${agentBase}/settings` ||
182			pathname === `${agentBase}/settings/`;
183		const isSkillsTab =
184			isAgentSkillsTab(owner, agentId, pathname) ||
185			isAgentSkillsSubPage(owner, agentId, pathname);
186		const agentConfigTab = pathname.match(
187			`/${owner}/agents/${agentId}/([^/]+)`,
188		)?.[1];
189		const activeTab: AgentTab = isChat
190			? "chat"
191			: isBehaviorsTab
192				? "behaviors"
193				: isSkillsTab
194					? "skills"
195					: isIdentityTab
196						? "identity"
197						: isSettingsTab
198							? "settings"
199							: (parseAgentTab(agentConfigTab) ?? "behaviors");
200	
201		useEffect(() => {
202			if (agentNotFound) {
203				void navigate({ to: "/$owner", params: { owner }, replace: true });
204			}
205		}, [agentNotFound, navigate, owner]);
206	
207		const headerReady = selectedAgent !== null;
208	
209		return (
210			<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
211				{/* Single header row matching Home: identity + actions/tabs wrap together. */}
212				<div className="flex shrink-0 flex-col items-center px-4 lg:px-6">
213					{headerReady ? (
214						<div className="flex min-w-0 max-w-full flex-wrap items-center justify-center gap-x-2 gap-y-1">
215							<AgentHeaderTabs
216								owner={owner}
217								agentId={agentId}
218								activeTab={activeTab}
219							/>
220						</div>
221					) : (
222						<AgentWorkbenchHeaderSkeleton />
223					)}
224				</div>
225	
226				<div
227					className={cn(
228						"flex min-h-0 min-w-0 flex-1 flex-col px-4 lg:px-6",
229						isChat ? "overflow-hidden" : "overflow-y-auto",
230					)}
231				>
232					<Outlet />
233				</div>
234			</div>
235		);
236	}
237	
238	export function AgentConfigPane({
239		agent,
240		tab,
241		runId,
242	}: {
243		agent: AgentItem;
244		tab: AgentSection;
245		/** Slack config-approval deep link `?run_id`; when set, the ProposalReviewShell
246		 *  fetches the held builder proposal and the form prefills it for review. */
247		runId?: number;
248	}) {
249		return (
250			<div className="mx-auto w-full max-w-3xl pb-6">
251				<ProposalReviewShell
252					resource={{ kind: "agent", agentId: agent.agentId }}
253					runId={runId}
254				>
255					{({ reviewMode, proposal, controlsDisabled }) => (
256						<AgentEditorForm
257							key={agent.agentId}
258							mode={{ kind: "edit", agent }}
259							section={tab}
260							reviewMode={reviewMode}
261							reviewProposal={proposal}
262							reviewControlsDisabled={controlsDisabled}
263						/>
264					)}
265				</ProposalReviewShell>
266			</div>
267		);
268	}
269	
270	export function AgentConfigRoute({
271		owner,
272		agentId,
273		tab,
274		runId,
275	}: {
276		owner: string;
277		agentId: string;
278		tab: AgentSection;
279		runId?: number;
280	}) {
281		const { orgContext, hasOrgContext } = useOrgContext();
282		const { isLoading: isResolvedLoading } = useResolvedPath(
283			`/${owner}`,
284			orgContext,
285		);
286		const { isAuthenticated } = useAuthState();
287		const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
288		const canManageWorkspace = isAuthenticated && isMember;
