/** Deterministic initials for an agent's avatar glyph. */
function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

/**
 * Per-agent sub-pages in the sidebar. Chat is the agent row itself.
 *
 * Every destination is a sidebar row: with Identity folded into Settings and
 * Permissions folded into Guardrails, four rows cover the agent, so a tab
 * strip in the workbench would only be a second copy of this list.
 */
const AGENT_CHILD_ROWS = [
	{
		key: "behaviors",
		label: "Behaviors",
		icon: ListChecks,
		subpath: "behaviors",
	},
	{ key: "skills", label: "Skills", icon: Sparkles, subpath: "skills" },
	{
		key: "guardrails",
		label: "Guardrails",
		icon: Shield,
		subpath: "guardrails",
	},
	{ key: "settings", label: "Settings", icon: Settings, subpath: "settings" },
] as const;

/**
 * Right-aligned record count for a Context child row. Rendered even at zero —
 * an explicit 0 is the useful signal that a type exists but has nothing in it,
 * which is otherwise indistinguishable from the count still loading.
 */
function EntityCount({ count }: { count: number }) {
	return (
		<span className="shrink-0 text-[11px] tabular-nums text-sidebar-foreground/40">
			{count}
			</CollapsibleContent>
		</Collapsible>
	);
}

/**
 * One agent in the roster: the row links to the agent's chat, the chevron
 * expands Behaviors / Skills / Guardrails / Settings. Only the route-active
 * agent is expanded by default; the rest render collapsed.
 */
function AgentGroup({
	ownerSlug,
	agentId,
	name,
	status,
	selected,
	pathname,
}: {
	ownerSlug: string;
	agentId: string;
	name: string;
	status: "active" | "idle";
	selected: boolean;
	pathname: string;
}) {
	const working = status === "active";
	const chat = agentChatLink(ownerSlug, agentId);
	const base = `/${ownerSlug}/agents/${agentId}`;
	const { open, setOpen } = useRouteDefaultOpen(selected);
	const activeChildKey = AGENT_CHILD_ROWS.find((child) =>
		pathname.startsWith(`${base}/${child.subpath}`),
	)?.key;

	return (
		<Collapsible open={open} onOpenChange={setOpen}>
			<div
				className={cn(
					"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-2 text-sm transition-colors",
					// On chat (or any sub-page without a child), the agent row is
					// the active highlight. On a listed config route the child takes it.
					selected && !(open && activeChildKey)
						? "bg-sidebar-accent text-sidebar-accent-foreground"
						: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
				)}
			>
				<Link
					to={chat.to}
					params={chat.params}
					className="flex min-w-0 flex-1 items-center gap-2"
				>
					<span className="relative flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-full bg-sidebar-accent text-[9px] font-semibold text-sidebar-accent-foreground">
						{agentInitial(name)}
						<span
							className={cn(
								"absolute -bottom-0.5 -right-0.5 h-[7px] w-[7px] rounded-full border-[1.5px] border-sidebar-background",
								working ? "bg-emerald-500" : "bg-sidebar-foreground/30",
							)}
						/>
					</span>
					<span className="min-w-0 flex-1 truncate">{name}</span>
					{working ? (
						<span className="shrink-0 text-[10px] text-sidebar-foreground/40">
							working
						</span>
					) : null}
				</Link>
				<CollapsibleTrigger asChild>
					<button
						type="button"
						aria-label={open ? `Collapse ${name}` : `Expand ${name}`}
						title={open ? `Collapse ${name}` : `Expand ${name}`}
						className="shrink-0"
					>
						<GroupChevron open={open} />
					</button>
				</CollapsibleTrigger>
			</div>
			<CollapsibleContent>
				{AGENT_CHILD_ROWS.map((child) => (
					<NavRow
						key={child.key}
						to={`/$owner/agents/$agentId/${child.subpath}`}
						params={{ owner: ownerSlug, agentId }}
						active={activeChildKey === child.key}
						icon={child.icon}
						label={child.label}
						indent
					/>
				))}
			</CollapsibleContent>
		</Collapsible>
	);
}

function UserMenu() {
	const navigate = useNavigate();
	const { session } = useAuthState();
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	const userName = session?.user?.name?.trim() || "You";
	return (
		<div className="border-t border-sidebar-border p-2">
			<DropdownMenu>
				<DropdownMenuTrigger asChild>
					<button
						type="button"
						className="flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-sm text-sidebar-foreground/80 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<CircleUser className="h-4 w-4 shrink-0 text-sidebar-foreground/60" />
						<span className="min-w-0 flex-1 truncate text-left">
							{userName}
						</span>
						<ChevronDown className="h-4 w-4 shrink-0 text-sidebar-foreground/40" />
					</button>
				</DropdownMenuTrigger>
				<DropdownMenuContent align="start" side="top" className="min-w-[12rem]">
					<DropdownMenuItem
						onSelect={() => void navigate({ to: "/account/settings" })}
					>
						<Settings2 className="h-4 w-4" />

