import type { ReactNode } from "react";
import { AgentGuardrailsCreate } from "@/components/agents/agent-guardrails-create";
import { AgentGuardrailsIndex } from "@/components/agents/agent-guardrails-index";
import { AgentPermissionsMatrix } from "@/components/agents/agent-permissions-matrix";
import { AgentSubpageShell } from "@/components/agents/agent-subpage-shell";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import { FILLED_BOX, cn } from "@/lib/utils";

function GuardrailsShell({
	owner,
	agentId,
	children,
	showBack,
}: {
	owner: string;
	agentId: string;
	children: ReactNode;
	showBack?: boolean;
}) {
	return (
		<AgentSubpageShell
			owner={owner}
			agentId={agentId}
			showBack={showBack}
			backLabel="Guardrails"
			backTo="/$owner/agents/$agentId/guardrails"
		>
			{children}
		</AgentSubpageShell>
	);
}

export function AgentGuardrailsIndexRoute({
	owner,
	agentId,
	expandedName,
}: {
	owner: string;
	agentId: string;
	/** When set, that guardrail's row is expanded in place to show its config. */
	expandedName?: string;
}) {
	// Permission endpoints require an org settings admin.
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	return (
		<GuardrailsShell owner={owner} agentId={agentId}>
			<div className="space-y-6">
				<AgentGuardrailsIndex
					owner={owner}
					agentId={agentId}
					expandedName={expandedName}
				/>
				{isAdmin ? (
					<section
						id="access"
						className={cn(FILLED_BOX, "space-y-4 p-4")}
					>
						<div>
							<h2 className="text-sm font-semibold">Access</h2>
							<p className="mt-1 text-xs text-muted-foreground">
								Control which data, agent settings, and connector actions this
								agent may use automatically, with approval, or not at all.
							</p>
						</div>
						<div className="overflow-x-auto">
							<AgentPermissionsMatrix owner={owner} agentId={agentId} />
						</div>
					</section>
				) : null}
			</div>
		</GuardrailsShell>
	);
}

export function AgentGuardrailsCreateRoute({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	return (
		<GuardrailsShell owner={owner} agentId={agentId} showBack>
			<AgentGuardrailsCreate owner={owner} agentId={agentId} />
		</GuardrailsShell>
	);
}

export function AgentGuardrailDetailRoute({
	owner,
	agentId,
	name,
}: {
	owner: string;
	agentId: string;
	/** Still URL-encoded — decoded here before lookup. */
	name: string;
}) {
	// The detail "page" is the guardrail list with the chosen row expanded in
	// place — deep-linkable, but it reads as the card opening inline.
	return (
		<AgentGuardrailsIndexRoute
			owner={owner}
			agentId={agentId}
			expandedName={decodeURIComponent(name)}
		/>
	);
}

