1	import { useCallback, useEffect, useState } from "react";
2	import { toast } from "sonner";
3	import { buildGeneratedAgentId } from "@/components/agents/agent-id-utils";
4	import {
5		overlayFromProposal,
6		type ReviewMode,
7	} from "@/components/agents/config-prefill";
8	import { ModelsListEditor } from "@/components/agents/models-list-editor";
9	
10	import { Button } from "@/components/ui/button";
11	import { Checkbox } from "@/components/ui/checkbox";
12	import { FormLoadingShell } from "@/components/ui/form-loading-shell";
13	import { Input } from "@/components/ui/input";
14	import { Label } from "@/components/ui/label";
15	import {
16		Select,
17		SelectContent,
18		SelectItem,
19		SelectTrigger,
20		SelectValue,
21	} from "@/components/ui/select";
22	import { Textarea } from "@/components/ui/textarea";
23	import {
24		type AgentItem,
25		type PendingProposal,
26		useAgentConfig,
27		useCreateAgent,
28		useDeleteAgent,
29		useSandboxes,
30		useUpdateAgent,
31		useUpdateAgentConfig,
32	} from "@/lib/api";
33	
34	export type AgentEditorMode =
35		| { kind: "create" }
36		| { kind: "edit"; agent: AgentItem };
37	
38	/** Which slice of the agent editor to render. Each maps to a tab on the agent
39	 *  detail page; the create flow ignores it (only the name/description show). */
40	export type AgentSection =
41		| "settings"
42		| "identity"
43		| "skills"
44		| "platforms"
45		| "guardrails";
46	
47	/**
48	 * The agent create/edit form. Rendered inline inside an agent-detail tab
49	 * (one `section` per tab) or on the create page. One `<form>` / one save
50	 * covers Identity + Guardrails (they round-trip together);
51	 * Providers, Skills, and Reach self-save on dedicated routes.
52	 */
53	export function AgentEditorForm({
54		mode,
55		section = "identity",
56		existingAgentIds = [],
57		onCreated,
58		onCancel,
59		onDone,
60		reviewMode = "none",
61		reviewProposal = null,
62		reviewControlsDisabled = false,
63	}: {
64		mode: AgentEditorMode;
65		section?: AgentSection;
66		existingAgentIds?: string[];
67		onCreated?: (agentId: string) => void | Promise<void>;
68		onCancel?: () => void;
69		/** Called after a successful save/delete (and after create if no onCreated). */
70		onDone?: () => void;
71		/** Config-approval review state, supplied by the wrapping {@link ProposalReviewShell}
72		 *  (Slack deep link `?run_id`). The shell owns the fetch + lifecycle + Approve/
73		 *  Reject footer; this form only PREFILLS the proposed values (read-only) and
74		 *  hides its own Save/Delete footer during an active review. Defaults ⇒ normal
75		 *  edit (no review). */
76		reviewMode?: ReviewMode;
77		/** The held proposal to overlay when reviewMode is active; null otherwise. */
78		reviewProposal?: PendingProposal | null;
79		/** True when the shell says editable controls must be locked (fail-closed). */
80		reviewControlsDisabled?: boolean;
81	}) {
82		const isCreate = mode.kind === "create";
83		const selectedAgent = mode.kind === "edit" ? mode.agent : null;
84		const needsConfigEditorData =
85			!isCreate &&
86			section !== "platforms" &&
87			section !== "skills" &&
88			!!selectedAgent;
89		const createAgent = useCreateAgent();
90		const updateAgent = useUpdateAgent(selectedAgent?.agentId ?? "");
91		const deleteAgent = useDeleteAgent(selectedAgent?.agentId ?? "");
92		const updateAgentConfig = useUpdateAgentConfig(selectedAgent?.agentId ?? "");
93		const { data: agentConfig, isLoading: isConfigLoading } = useAgentConfig(
94			selectedAgent?.agentId,
95			{ enabled: needsConfigEditorData },
96		);
97	
98		// Review state is owned by the wrapping ProposalReviewShell and threaded in as
99		// props; this form only consumes it to prefill + lock. `create` is never a
100		// review (no agent to change), so ignore any review props then.
101		const reviewActive = !isCreate && reviewMode === "active";
102		const pendingProposal = reviewActive ? reviewProposal : null;
103	
104		// Callers remount this form (key on the agent id, or 'create') when the
105		// target changes, so initial state can come straight from `mode` and the
106		// async-loaded config below.
107		const [name, setName] = useState(() =>
108			mode.kind === "edit" ? mode.agent.name : "",
109		);
110		const [description, setDescription] = useState(() =>
111			mode.kind === "edit" ? (mode.agent.description ?? "") : "",
112		);
113		const [identityMd, setIdentityMd] = useState("");
114		const [soulMd, setSoulMd] = useState("");
115		const [userMd, setUserMd] = useState("");
116		const [models, setModels] = useState<string[]>([]);
117		const [showToolCalls, setShowToolCalls] = useState(false);
118		const [sandboxId, setSandboxId] = useState<string>("builtin");
119		const [confirmingDeleteAgent, setConfirmingDeleteAgent] = useState(false);
120	
121		const { data: sandboxesData } = useSandboxes({
122			enabled: section === "settings" && !isCreate,
123		});
124	
125		useEffect(() => {
126			if (!selectedAgent || !agentConfig) return;
127			setIdentityMd(agentConfig.identityMd ?? "");
128			setSoulMd(agentConfig.soulMd ?? "");
129			setUserMd(agentConfig.userMd ?? "");
130			setModels(
131				(agentConfig as { models?: string[] }).models ??
132					(agentConfig as { settings?: { models?: string[] } }).settings
133						?.models ??
134					[],
135			);
136			// Config returns it flat; the resolved shape nests under `settings`.
137			setShowToolCalls(
138				(agentConfig as { showToolCalls?: boolean }).showToolCalls ??
139					(agentConfig as { settings?: { showToolCalls?: boolean } }).settings
140						?.showToolCalls ??
141					false,
142			);
143			setSandboxId(
144				(agentConfig as { sandboxId?: string | null }).sandboxId ??
145					(agentConfig as { settings?: { sandboxId?: string | null } }).settings
146						?.sandboxId ??
147					"builtin",
148			);
149	
150			// Config-approval review: overlay the held proposal ON TOP of the just-
151			// hydrated config, in the SAME effect so the base values can never clobber
152			// the proposed ones (single write, no cross-effect race). Only keys the
153			// proposal carries are overlaid; the rest keep their server values.
154			if (pendingProposal) {
155				const overlay = overlayFromProposal(pendingProposal.proposal);
156				if (overlay.name !== undefined) setName(overlay.name);
157				if (overlay.description !== undefined)
158					setDescription(overlay.description);
159				if (overlay.identityMd !== undefined) setIdentityMd(overlay.identityMd);
160			}
161		}, [agentConfig, selectedAgent, pendingProposal]);
162	
163		const handleSubmit = useCallback(
164			async (event: React.FormEvent) => {
165				event.preventDefault();
166	
167				if (isCreate) {
168					const created = await createAgent.mutateAsync({
169						agentId: buildGeneratedAgentId(name, existingAgentIds),
170						name: name.trim(),
171						description: description.trim() || undefined,
172					});
173					if (onCreated) {
174						await onCreated(created.agentId);
175					} else {
176						onDone?.();
177					}
178					return;
179				}
180	
181				if (!selectedAgent) return;
182				// Guard the race where the form is submitted before the agent config
183				// has loaded — local rows would still be empty and would wipe identity,
184				// providers, and skills on the server. Only `agentConfig` is required:
185				// the provider/skill/guardrail catalogs are display-only enrichment for
186				// the "add" pickers (the row builders preserve the agent's own config
187				// without them), so they must NOT gate saving — an unavailable or slow
188				// catalog would otherwise silently block every section's save.
189				if (!agentConfig) {
190					toast.error("Still loading agent settings — try again in a moment");
191					return;
192				}
193	
194				try {
195					await Promise.all([
196						updateAgent.mutateAsync({
197							name: name.trim() || selectedAgent.name,
198							description: description.trim() || undefined,
199						}),
200						updateAgentConfig.mutateAsync({
201							identityMd: identityMd.trim(),
202							soulMd: soulMd.trim(),
203							userMd: userMd.trim(),
204							models,
205							authProfiles: agentConfig.authProfiles ?? [],
206							skillsConfig: agentConfig.skillsConfig,
207							showToolCalls,
208							sandboxId: sandboxId === "builtin" ? undefined : sandboxId,
209						}),
210					]);
211					toast.success("Agent saved");
212					onDone?.();
213				} catch (error) {
214					toast.error(
215						error instanceof Error ? error.message : "Failed to save agent",
216					);
217				}
218			},
219			[
220				agentConfig,
221				createAgent,
222				description,
223				sandboxId,
224				existingAgentIds,
225				identityMd,
226				isCreate,
227				models,
228				name,
229				onCreated,
230				onDone,
231				selectedAgent,
232				showToolCalls,
233				soulMd,
234				updateAgent,
235				updateAgentConfig,
236				userMd,
237			],
238		);
239	
240		const handleDelete = useCallback(async () => {
241			if (!selectedAgent) return;
242			await deleteAgent.mutateAsync();
243			setConfirmingDeleteAgent(false);
244			onDone?.();
245		}, [deleteAgent, onDone, selectedAgent]);
246	
247		const isPending =
248			createAgent.isPending ||
249			updateAgent.isPending ||
250			deleteAgent.isPending ||
251			updateAgentConfig.isPending;
252		// Save depends only on the agent's own config being loaded; the provider/
253		// skill/guardrail catalogs are optional display enrichment (see handleSubmit)
254		// and must not gate Save, so it keeps working when a catalog is unavailable.
255		const configReady = isCreate || !!agentConfig;
256	
257		// The shell computes the fail-closed review lock (active/loading/error);
258		// combine it with this form's own in-flight save so inputs disable during a
259		// save too. Approve applies the SERVER-HELD proposal, so an editable field
260		// during review would silently diverge from what's applied.
261		const controlsDisabled = isPending || reviewControlsDisabled;
262	
263		// During an active review the shell renders the Approve/Reject footer; this
264		// form must hide its own Save/Delete footer. On loading/error the shell holds
265		// its footer too, and this form suppresses Save (fail closed). Only `none` and
266		// the explicit `gone` 404 (which restores editing) show the Save/Delete footer.
267		const showEditFooter = reviewMode === "none" || reviewMode === "gone";
268	
269		const canSubmit = name.trim().length > 0 && configReady;
270	
271		const showNameFields = isCreate || section === "settings";
272		// Identity (system prompt) folded into Settings — it renders at the top of
273		// the Settings section, above name/general/danger-zone. The standalone
274		// "identity" section value stays valid (old /identity URLs still resolve)
275		// but no longer has its own visible tab.
276		const showIdentityFields =
277			!isCreate && (section === "identity" || section === "settings");
278		const showDelete = !isCreate && section === "settings";
279		const showChatPrefs = !isCreate && section === "settings";
280	
281		return (
282			<form onSubmit={handleSubmit} className="flex min-h-0 flex-col">
283				<div className="grid content-start gap-4 py-2">
284					{/* Review banners live in the wrapping ProposalReviewShell, not here. */}
285					{showIdentityFields ? (
286						isConfigLoading ? (
287							<FormLoadingShell rows={4} />
288						) : (
289							<>
290								<div className="grid gap-2">
291									<Label htmlFor="identity-md">Identity</Label>
292									<Textarea
293										id="identity-md"
294										rows={6}
295										value={identityMd}
296										onChange={(event) => setIdentityMd(event.target.value)}
297										disabled={controlsDisabled}
298										placeholder="You are a market intelligence agent. Track competitors, analyze launches and signals, and surface concise, decision-ready insights."
299									/>
300								</div>
301								<div className="grid gap-2">
302									<Label htmlFor="soul-md">Soul</Label>
303									<Textarea
304										id="soul-md"
305										rows={6}
306										value={soulMd}
307										onChange={(event) => setSoulMd(event.target.value)}
308										disabled={controlsDisabled}
309										placeholder="Be rigorous, skeptical of weak signals, and calm under ambiguity. Prefer crisp summaries, explicit evidence, and clear confidence levels."
310									/>
311								</div>
312								<div className="grid gap-2">
313									<Label htmlFor="user-md">User prompt</Label>
314									<Textarea
315										id="user-md"
316										rows={6}
317										value={userMd}
318										onChange={(event) => setUserMd(event.target.value)}
319										disabled={controlsDisabled}
320										placeholder="Monitor the market for notable competitor moves, pricing changes, launches, partnerships, and customer sentiment shifts. Summarize what changed, why it matters, and what to watch next."
321									/>
322								</div>
323							</>
324						)
325					) : null}
326	
327					{showNameFields ? (
328						<>
329							<div className="grid gap-2">
330								<Label htmlFor="agent-name">
331									Name <span className="ml-1 text-destructive">*</span>
332								</Label>
333								<Input
334									id="agent-name"
335									placeholder="Support Bot"
336									value={name}
337									onChange={(event) => setName(event.target.value)}
338									disabled={controlsDisabled}
339									required
340								/>
341								{isCreate ? (
342									<p className="text-[11px] text-muted-foreground">
343										The agent ID will be generated automatically from the name.
344									</p>
345								) : null}
346							</div>
347	
348							<div className="grid gap-2">
349								<Label htmlFor="agent-description">Description</Label>
350								<Textarea
351									id="agent-description"
352									placeholder="Handles customer support and triage across channels."
353									value={description}
354									onChange={(event) => setDescription(event.target.value)}
355									disabled={controlsDisabled}
356									rows={3}
357								/>
358							</div>
359						</>
360					) : null}
361	
362					{showChatPrefs ? (
363						<div className="flex items-start gap-3 rounded-lg border bg-muted/20 p-3">
364							<Checkbox
365								id="show-tool-calls"
366								checked={showToolCalls}
367								onCheckedChange={(checked) => setShowToolCalls(checked === true)}
368								disabled={controlsDisabled}
369								className="mt-0.5"
370							/>
371							<div className="grid gap-0.5">
372								<Label htmlFor="show-tool-calls" className="cursor-pointer">
373									Show tool calls in chat
374								</Label>
375								<p className="text-[11px] text-muted-foreground">
376									Render the agent's tool invocations (name, arguments, and
377									result) as cards in the web chat. Off by default.
378								</p>
379							</div>
380						</div>
381					) : null}
382	
383					{showChatPrefs ? (
384						<div className="grid gap-2">
385							<Label>Models</Label>
386							<ModelsListEditor
387								value={models}
388								onChange={setModels}
389								disabled={controlsDisabled}
390							/>
391							<p className="text-[11px] text-muted-foreground">
392								Ordered list; the first is the default. Only these models may be
393								used — a request for anything else falls back to the first
394								available one. Leave empty to use the org default.
395							</p>
396						</div>
397					) : null}
398	
399					{showChatPrefs ? (
400						<div className="grid gap-2">
401							<Label htmlFor="agent-sandbox">Run in sandbox</Label>
402							<Select
403								value={sandboxId}
404								onValueChange={setSandboxId}
405								disabled={controlsDisabled}
406							>
407								<SelectTrigger id="agent-sandbox" className="w-full">
408									<SelectValue placeholder="Built-in" />
409								</SelectTrigger>
410								<SelectContent>
411									<SelectItem value="builtin">Built-in (default)</SelectItem>
412									{(sandboxesData?.sandboxes ?? []).map((sandbox) => (
413										<SelectItem key={sandbox.id} value={sandbox.id}>
414											{sandbox.name} ({sandbox.providerKind})
415											{sandbox.connected ? "" : " — no credential"}
416										</SelectItem>
417									))}
418								</SelectContent>
419							</Select>
420							<p className="text-[11px] text-muted-foreground">
421								Where this agent's commands execute. Built-in runs in-process;
422								sandboxes run on a connected provider. Manage sandboxes under
423								Connect › Runtime.
424							</p>
425						</div>
426					) : null}
427				</div>
428	
429				{/* During an active review the shell renders Approve/Reject below this
430				    form; on loading/error the shell holds its footer. This form shows its
431				    Save/Delete footer only when NOT reviewing (none) or after the run
432				    resolved (gone → editing restored). */}
433				{!showEditFooter ? null : (
434					<div className="mt-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
435						{showDelete ? (
436							confirmingDeleteAgent ? (
437								<div className="flex flex-col gap-2 sm:flex-row">
438									<Button
439										type="button"
440										variant="destructive"
441										onClick={() => void handleDelete()}
442										disabled={deleteAgent.isPending}
443									>
444										{deleteAgent.isPending ? "Deleting..." : "Delete agent"}
445									</Button>
446									<Button
447										type="button"
448										variant="outline"
449										onClick={() => setConfirmingDeleteAgent(false)}
450										disabled={deleteAgent.isPending}
451									>
452										Cancel
453									</Button>
454								</div>
455							) : (
456								<Button
457									type="button"
458									variant="outline"
459									className="text-destructive hover:text-destructive"
460									onClick={() => setConfirmingDeleteAgent(true)}
461									disabled={deleteAgent.isPending}
462								>
463									Delete agent
464								</Button>
465							)
466						) : (
467							<span />
468						)}
469						<div className="flex flex-col gap-2 sm:flex-row">
470							{onCancel ? (
471								<Button
472									type="button"
473									variant="outline"
474									onClick={onCancel}
475									disabled={isPending}
476								>
477									Cancel
478								</Button>
479							) : null}
480							<Button type="submit" disabled={!canSubmit || isPending}>
481								{isCreate
482									? createAgent.isPending
483										? "Creating..."
484										: "Create agent"
485									: updateAgent.isPending || updateAgentConfig.isPending
486										? "Saving..."
487										: "Save changes"}
488							</Button>
489						</div>
490					</div>
491				)}
492			</form>
493		);
494	}
