import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { buildGeneratedAgentId } from "@/components/agents/agent-id-utils";
import {
	overlayFromProposal,
	type ReviewMode,
} from "@/components/agents/config-prefill";
import { ModelsListEditor } from "@/components/agents/models-list-editor";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { FormLoadingShell } from "@/components/ui/form-loading-shell";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
	type AgentItem,
	type PendingProposal,
	useAgentConfig,
	useCreateAgent,
	useDeleteAgent,
	useSandboxes,
	useUpdateAgent,
	useUpdateAgentConfig,
} from "@/lib/api";

export type AgentEditorMode =
	| { kind: "create" }
	| { kind: "edit"; agent: AgentItem };

/** Which slice of the agent editor to render. Each maps to a tab on the agent
 *  detail page; the create flow ignores it (only the name/description show). */
export type AgentSection =
	| "settings"
	| "identity"
	| "skills"
	| "platforms"
	| "guardrails";

/**
 * The agent create/edit form. Rendered inline inside an agent-detail tab
 * (one `section` per tab) or on the create page. One `<form>` / one save
 * covers Identity + Guardrails (they round-trip together);
 * Providers, Skills, and Reach self-save on dedicated routes.
 */
export function AgentEditorForm({
	mode,
	section = "identity",
	existingAgentIds = [],
	onCreated,
	onCancel,
	onDone,
	reviewMode = "none",
	reviewProposal = null,
	reviewControlsDisabled = false,
}: {
	mode: AgentEditorMode;
	section?: AgentSection;
	existingAgentIds?: string[];
	onCreated?: (agentId: string) => void | Promise<void>;
	onCancel?: () => void;
	/** Called after a successful save/delete (and after create if no onCreated). */
	onDone?: () => void;
	/** Config-approval review state, supplied by the wrapping {@link ProposalReviewShell}
	 *  (Slack deep link `?run_id`). The shell owns the fetch + lifecycle + Approve/
	 *  Reject footer; this form only PREFILLS the proposed values (read-only) and
	 *  hides its own Save/Delete footer during an active review. Defaults ⇒ normal
	 *  edit (no review). */
	reviewMode?: ReviewMode;
	/** The held proposal to overlay when reviewMode is active; null otherwise. */
	reviewProposal?: PendingProposal | null;
	/** True when the shell says editable controls must be locked (fail-closed). */
	reviewControlsDisabled?: boolean;
}) {
	const isCreate = mode.kind === "create";
	const selectedAgent = mode.kind === "edit" ? mode.agent : null;
	const needsConfigEditorData =
		!isCreate &&
		section !== "platforms" &&
		section !== "skills" &&
		!!selectedAgent;
	const createAgent = useCreateAgent();
	const updateAgent = useUpdateAgent(selectedAgent?.agentId ?? "");
	const deleteAgent = useDeleteAgent(selectedAgent?.agentId ?? "");
	const updateAgentConfig = useUpdateAgentConfig(selectedAgent?.agentId ?? "");
	const { data: agentConfig, isLoading: isConfigLoading } = useAgentConfig(
		selectedAgent?.agentId,
		{ enabled: needsConfigEditorData },
	);

	// Review state is owned by the wrapping ProposalReviewShell and threaded in as
	// props; this form only consumes it to prefill + lock. `create` is never a
	// review (no agent to change), so ignore any review props then.
	const reviewActive = !isCreate && reviewMode === "active";
	const pendingProposal = reviewActive ? reviewProposal : null;

	// Callers remount this form (key on the agent id, or 'create') when the
	// target changes, so initial state can come straight from `mode` and the
	// async-loaded config below.
	const [name, setName] = useState(() =>
		mode.kind === "edit" ? mode.agent.name : "",
	);
	const [description, setDescription] = useState(() =>
		mode.kind === "edit" ? (mode.agent.description ?? "") : "",
	);
	const [identityMd, setIdentityMd] = useState("");
	const [soulMd, setSoulMd] = useState("");
	const [userMd, setUserMd] = useState("");
	const [models, setModels] = useState<string[]>([]);
	const [showToolCalls, setShowToolCalls] = useState(false);
	const [sandboxId, setSandboxId] = useState<string>("builtin");
	const [confirmingDeleteAgent, setConfirmingDeleteAgent] = useState(false);

	const { data: sandboxesData } = useSandboxes({
		enabled: section === "settings" && !isCreate,
	});

	useEffect(() => {
		if (!selectedAgent || !agentConfig) return;
		setIdentityMd(agentConfig.identityMd ?? "");
		setSoulMd(agentConfig.soulMd ?? "");
		setUserMd(agentConfig.userMd ?? "");
		setModels(
			(agentConfig as { models?: string[] }).models ??
				(agentConfig as { settings?: { models?: string[] } }).settings
					?.models ??
				[],
		);
		// Config returns it flat; the resolved shape nests under `settings`.
		setShowToolCalls(
			(agentConfig as { showToolCalls?: boolean }).showToolCalls ??
				(agentConfig as { settings?: { showToolCalls?: boolean } }).settings
					?.showToolCalls ??
				false,
		);
		setSandboxId(
			(agentConfig as { sandboxId?: string | null }).sandboxId ??
				(agentConfig as { settings?: { sandboxId?: string | null } }).settings
					?.sandboxId ??
				"builtin",
		);

		// Config-approval review: overlay the held proposal ON TOP of the just-
		// hydrated config, in the SAME effect so the base values can never clobber
		// the proposed ones (single write, no cross-effect race). Only keys the
		// proposal carries are overlaid; the rest keep their server values.
		if (pendingProposal) {
			const overlay = overlayFromProposal(pendingProposal.proposal);
			if (overlay.name !== undefined) setName(overlay.name);
			if (overlay.description !== undefined)
				setDescription(overlay.description);
			if (overlay.identityMd !== undefined) setIdentityMd(overlay.identityMd);
		}
	}, [agentConfig, selectedAgent, pendingProposal]);

	const handleSubmit = useCallback(
		async (event: React.FormEvent) => {
			event.preventDefault();

			if (isCreate) {
				const created = await createAgent.mutateAsync({
					agentId: buildGeneratedAgentId(name, existingAgentIds),
					name: name.trim(),
					description: description.trim() || undefined,
				});
				if (onCreated) {
					await onCreated(created.agentId);
				} else {
					onDone?.();
				}
				return;
			}

			if (!selectedAgent) return;
			// Guard the race where the form is submitted before the agent config
			// has loaded — local rows would still be empty and would wipe identity,
			// providers, and skills on the server. Only `agentConfig` is required:
			// the provider/skill/guardrail catalogs are display-only enrichment for
			// the "add" pickers (the row builders preserve the agent's own config
			// without them), so they must NOT gate saving — an unavailable or slow
			// catalog would otherwise silently block every section's save.
			if (!agentConfig) {
				toast.error("Still loading agent settings — try again in a moment");
				return;
			}

			try {
				await Promise.all([
					updateAgent.mutateAsync({
						name: name.trim() || selectedAgent.name,
						description: description.trim() || undefined,
					}),
					updateAgentConfig.mutateAsync({
						identityMd: identityMd.trim(),
						soulMd: soulMd.trim(),
						userMd: userMd.trim(),
						models,
						authProfiles: agentConfig.authProfiles ?? [],
						skillsConfig: agentConfig.skillsConfig,
						showToolCalls,
						sandboxId: sandboxId === "builtin" ? undefined : sandboxId,
					}),
				]);
				toast.success("Agent saved");
				onDone?.();
			} catch (error) {
				toast.error(
					error instanceof Error ? error.message : "Failed to save agent",
				);
			}
		},
		[
			agentConfig,
			createAgent,
			description,
			sandboxId,
			existingAgentIds,
			identityMd,
			isCreate,
			models,
			name,
			onCreated,
			onDone,
			selectedAgent,
			showToolCalls,
			soulMd,
			updateAgent,
			updateAgentConfig,
			userMd,
		],
	);

	const handleDelete = useCallback(async () => {
		if (!selectedAgent) return;
		await deleteAgent.mutateAsync();
		setConfirmingDeleteAgent(false);
		onDone?.();
	}, [deleteAgent, onDone, selectedAgent]);

	const isPending =
		createAgent.isPending ||
		updateAgent.isPending ||
		deleteAgent.isPending ||
		updateAgentConfig.isPending;
	// Save depends only on the agent's own config being loaded; the provider/
	// skill/guardrail catalogs are optional display enrichment (see handleSubmit)
	// and must not gate Save, so it keeps working when a catalog is unavailable.
	const configReady = isCreate || !!agentConfig;

	// The shell computes the fail-closed review lock (active/loading/error);
	// combine it with this form's own in-flight save so inputs disable during a
	// save too. Approve applies the SERVER-HELD proposal, so an editable field
	// during review would silently diverge from what's applied.
	const controlsDisabled = isPending || reviewControlsDisabled;

	// During an active review the shell renders the Approve/Reject footer; this
	// form must hide its own Save/Delete footer. On loading/error the shell holds
	// its footer too, and this form suppresses Save (fail closed). Only `none` and
	// the explicit `gone` 404 (which restores editing) show the Save/Delete footer.
	const showEditFooter = reviewMode === "none" || reviewMode === "gone";

	const canSubmit = name.trim().length > 0 && configReady;

	const showNameFields = isCreate || section === "settings";
	// Identity (system prompt) folded into Settings — it renders at the top of
	// the Settings section, above name/general/danger-zone. The standalone
	// "identity" section value stays valid (old /identity URLs still resolve)
	// but no longer has its own visible tab.
	const showIdentityFields =
		!isCreate && (section === "identity" || section === "settings");
	const showDelete = !isCreate && section === "settings";
	const showChatPrefs = !isCreate && section === "settings";

	return (
		<form onSubmit={handleSubmit} className="flex min-h-0 flex-col">
			<div className="grid content-start gap-4 py-2">
				{/* Review banners live in the wrapping ProposalReviewShell, not here. */}
				{showIdentityFields ? (
					isConfigLoading ? (
						<FormLoadingShell rows={4} />
					) : (
						<>
							<div className="grid gap-2">
								<Label htmlFor="identity-md">Identity</Label>
								<Textarea
									id="identity-md"
									rows={6}
									value={identityMd}
									onChange={(event) => setIdentityMd(event.target.value)}
									disabled={controlsDisabled}
									placeholder="You are a market intelligence agent. Track competitors, analyze launches and signals, and surface concise, decision-ready insights."
								/>
							</div>
							<div className="grid gap-2">
								<Label htmlFor="soul-md">Soul</Label>
								<Textarea
									id="soul-md"
									rows={6}
									value={soulMd}
									onChange={(event) => setSoulMd(event.target.value)}
									disabled={controlsDisabled}
									placeholder="Be rigorous, skeptical of weak signals, and calm under ambiguity. Prefer crisp summaries, explicit evidence, and clear confidence levels."
								/>
							</div>
							<div className="grid gap-2">
								<Label htmlFor="user-md">User prompt</Label>
								<Textarea
									id="user-md"
									rows={6}
									value={userMd}
									onChange={(event) => setUserMd(event.target.value)}
									disabled={controlsDisabled}
									placeholder="Monitor the market for notable competitor moves, pricing changes, launches, partnerships, and customer sentiment shifts. Summarize what changed, why it matters, and what to watch next."
								/>
							</div>
						</>
					)
				) : null}

				{showNameFields ? (
					<>
						<div className="grid gap-2">
							<Label htmlFor="agent-name">
								Name <span className="ml-1 text-destructive">*</span>
							</Label>
							<Input
								id="agent-name"
								placeholder="Support Bot"
								value={name}
								onChange={(event) => setName(event.target.value)}
								disabled={controlsDisabled}
								required
							/>
							{isCreate ? (
								<p className="text-[11px] text-muted-foreground">
									The agent ID will be generated automatically from the name.
								</p>
							) : null}
						</div>

						<div className="grid gap-2">
							<Label htmlFor="agent-description">Description</Label>
							<Textarea
								id="agent-description"
								placeholder="Handles customer support and triage across channels."
								value={description}
								onChange={(event) => setDescription(event.target.value)}
								disabled={controlsDisabled}
								rows={3}
							/>
						</div>
					</>
				) : null}

				{showChatPrefs ? (
					<div className="flex items-start gap-3 rounded-lg border bg-muted/20 p-3">
						<Checkbox
							id="show-tool-calls"
							checked={showToolCalls}
							onCheckedChange={(checked) => setShowToolCalls(checked === true)}
							disabled={controlsDisabled}
							className="mt-0.5"
						/>
						<div className="grid gap-0.5">
							<Label htmlFor="show-tool-calls" className="cursor-pointer">
								Show tool calls in chat
							</Label>
							<p className="text-[11px] text-muted-foreground">
								Render the agent's tool invocations (name, arguments, and
								result) as cards in the web chat. Off by default.
							</p>
						</div>
					</div>
				) : null}

				{showChatPrefs ? (
					<div className="grid gap-2">
						<Label>Models</Label>
						<ModelsListEditor
							value={models}
							onChange={setModels}
							disabled={controlsDisabled}
						/>
						<p className="text-[11px] text-muted-foreground">
							Ordered list; the first is the default. Only these models may be
							used — a request for anything else falls back to the first
							available one. Leave empty to use the org default.
						</p>
					</div>
				) : null}

				{showChatPrefs ? (
					<div className="grid gap-2">
						<Label htmlFor="agent-sandbox">Run in sandbox</Label>
						<Select
							value={sandboxId}
							onValueChange={setSandboxId}
							disabled={controlsDisabled}
						>
							<SelectTrigger id="agent-sandbox" className="w-full">
								<SelectValue placeholder="Built-in" />
							</SelectTrigger>
							<SelectContent>
								<SelectItem value="builtin">Built-in (default)</SelectItem>
								{(sandboxesData?.sandboxes ?? []).map((sandbox) => (
									<SelectItem key={sandbox.id} value={sandbox.id}>
										{sandbox.name} ({sandbox.providerKind})
										{sandbox.connected ? "" : " — no credential"}
									</SelectItem>
								))}
							</SelectContent>
						</Select>
						<p className="text-[11px] text-muted-foreground">
							Where this agent's commands execute. Built-in runs in-process;
							sandboxes run on a connected provider. Manage sandboxes under
							Connect › Runtime.
						</p>
					</div>
				) : null}
			</div>

			{/* During an active review the shell renders Approve/Reject below this
			    form; on loading/error the shell holds its footer. This form shows its
			    Save/Delete footer only when NOT reviewing (none) or after the run
			    resolved (gone → editing restored). */}
			{!showEditFooter ? null : (
				<div className="mt-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
					{showDelete ? (
						confirmingDeleteAgent ? (
							<div className="flex flex-col gap-2 sm:flex-row">
								<Button
									type="button"
									variant="destructive"
									onClick={() => void handleDelete()}
									disabled={deleteAgent.isPending}
								>
									{deleteAgent.isPending ? "Deleting..." : "Delete agent"}
								</Button>
								<Button
									type="button"
									variant="outline"
									onClick={() => setConfirmingDeleteAgent(false)}
									disabled={deleteAgent.isPending}
								>
									Cancel
								</Button>
							</div>
						) : (
							<Button
								type="button"
								variant="outline"
								className="text-destructive hover:text-destructive"
								onClick={() => setConfirmingDeleteAgent(true)}
								disabled={deleteAgent.isPending}
							>
								Delete agent
							</Button>
						)
					) : (
						<span />
					)}
					<div className="flex flex-col gap-2 sm:flex-row">
						{onCancel ? (
							<Button
								type="button"
								variant="outline"
								onClick={onCancel}
								disabled={isPending}
							>
								Cancel
							</Button>
						) : null}
						<Button type="submit" disabled={!canSubmit || isPending}>
							{isCreate
								? createAgent.isPending
									? "Creating..."
									: "Create agent"
								: updateAgent.isPending || updateAgentConfig.isPending
									? "Saving..."
									: "Save changes"}
						</Button>
					</div>
				</div>
			)}
		</form>
	);
}

