29	} from "@/lib/api/inference-providers";
30	import { type SandboxItem, useSandboxes } from "@/lib/api/sandboxes";
31	import {
32	  CONNECTOR_FILTER_LABELS,
33	  type ConnectorFilter,
34	  connectorMatchesFilter,
35	  deriveConnectorFacets,
36	} from "@/lib/connectors/facets";
37	import { buildInferenceConnectorRows } from "@/lib/connectors/inference-rows";
38	import {
39	  buildSandboxConnectorRows,
40	  sandboxProviderFaviconDomain,
41	} from "@/lib/connectors/sandbox-rows";
42	import { OWNER_SECTIONS } from "@/lib/owner-sections";
43	
44	export const Route = createFileRoute("/$owner/connectors/")({
45	  validateSearch: (search: Record<string, unknown>): { entity_id?: string } =>
46	    typeof search.entity_id === "string" ? { entity_id: search.entity_id } : {},
47	  loader: ({ context: { queryClient }, params }) => {
48	    // Await nothing — every prefetch is fire-and-forget. The component
49	    // mounts on the first frame, and OwnerWorkspaceGate passes its loading
50	    // state through so the page chrome remains visible above the list skeleton.
51	    void queryClient.prefetchQuery(
52	      useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner })
53	    );
54	  },
55	  component: ConnectionsLandingPage,
56	});
57	
58	const FILTERS: ReadonlyArray<ConnectorFilter> = [
59	  "all",
60	  "data",
61	  "chat",
62	  "actions",
63	  "inference",
64	  "runtime",
65	  "oauth",
66	  "api_key",
67	  "app_install",
68	  "device",
69	  "needs_setup",
70	];
71	
72	function ConnectionsLandingPage() {
73	  const { owner } = Route.useParams();
74	  const { entity_id: entityIdParam } = Route.useSearch();
75	
76	  return (
77	    <OwnerWorkspaceGate owner={owner}>
78	      {(props) => (
79	        <ConnectionsLandingContent
80	          ownerSlug={props.ownerSlug}
81	          organizationId={props.organizationId}
82	          isWorkspaceLoading={props.isWorkspaceLoading}
83	          entityId={entityIdParam ? Number(entityIdParam) : undefined}
84	        />
85	      )}
86	    </OwnerWorkspaceGate>
87	  );
88	}
89	
90	function ConnectionsLandingContent({
91	  ownerSlug,
92	  organizationId,
93	  isWorkspaceLoading,
94	  entityId,
95	}: {
96	  ownerSlug: string;
97	  organizationId: string | null;
98	  isWorkspaceLoading: boolean;
99	  entityId?: number;
100	}) {
101	  const { data: groups = [], isLoading: isGroupsLoading } =
102	    useConnectionConnectorGroups(organizationId ?? "", { entityId });
103	  // The full installable catalog (installed org defs merged with bundled
104	  // catalog entries). The list renders only INSTALLED connectors (see the
105	  // items filter below); the catalog is still fetched here so uninstalled
106	  // entries can resolve display icons for any that slip through, and so the
107	  // "Add connector" page shares a warm cache. Browsing/adding uninstalled
108	  // connectors happens on /connectors/create, not here.
109	  const { data: installedDefs = [], isLoading: isDefsLoading } =
110	    useInstallableConnectorCatalog(organizationId ?? "");
111	  const { data: authProfiles = [] } = useAuthProfiles(organizationId, {});
112	  const { data: inferenceProviders = [], isLoading: isProvidersLoading } =
113	    useInferenceProviders({ enabled: entityId == null });
114	  // Provider rows join the inference catalog by `kind` for their icon — the
115	  // catalog is the only place a provider's logo lives.
116	  const { data: inferenceCatalog = [] } = useInferenceProviderCatalog({
117	    enabled: entityId == null,
118	  });
119	  // Sandboxes are org-wide remote runtimes; same scope rule as providers.
120	  const { data: sandboxesPayload, isLoading: isSandboxesLoading } =
121	    useSandboxes({ enabled: entityId == null });
122	  const isContentLoading =
123	    isWorkspaceLoading ||
124	    isGroupsLoading ||
125	    isDefsLoading ||
126	    (entityId == null && (isProvidersLoading || isSandboxesLoading));
127	  // Providers / sandboxes are org-wide, not entity-linked. Keep this explicit
128	  // guard because a disabled query can still return cached data.
129	  const scopedInferenceProviders =
130	    entityId == null ? inferenceProviders : [];
131	  const scopedSandboxes =
132	    entityId == null ? (sandboxesPayload?.sandboxes ?? []) : [];
133	
134	  // Page padding comes from the connectors layout. Center the list column.
135	  return (
136	    <div className="mx-auto flex w-full max-w-3xl flex-1 flex-col gap-6">
137	      {entityId != null && (
138	        <div className="flex items-center gap-2 rounded-lg bg-card px-3 py-2 text-sm">
139	          <Filter className="h-3.5 w-3.5 text-muted-foreground" />
140	          <span className="text-muted-foreground">
141	            Showing connectors linked to one entity
142	          </span>
143	          <Button asChild variant="ghost" size="sm" className="ml-auto h-6">
144	            <Link
145	              to="/$owner/connectors"
146	              params={{ owner: ownerSlug }}
147	              search={{}}
148	            >
149	              Show all
150	            </Link>
151	          </Button>
152	        </div>
153	      )}
154	
155	      <ConnectionsLandingInner
156	        ownerSlug={ownerSlug}
157	        isContentLoading={isContentLoading}
158	        groups={groups}
159	        installedDefs={installedDefs}
160	        authProfiles={authProfiles}
161	        inferenceProviders={scopedInferenceProviders}
162	        inferenceCatalog={inferenceCatalog}
163	        sandboxes={scopedSandboxes}
164	      />
165	    </div>
166	  );
167	}
168	
169	function ConnectionsLandingInner({
170	  ownerSlug,
171	  isContentLoading,
172	  groups,
173	  installedDefs,
174	  authProfiles,
175	  inferenceProviders,
176	  inferenceCatalog,
177	  sandboxes,
178	}: {
179	  ownerSlug: string;
180	  isContentLoading: boolean;
181	  groups: ConnectionConnectorGroup[];
182	  installedDefs: ConnectorDefinitionItem[];
183	  authProfiles: NonNullable<ReturnType<typeof useAuthProfiles>["data"]>;
184	  inferenceProviders: InferenceProviderItem[];
185	  inferenceCatalog: InferenceCatalogItem[];
186	  sandboxes: SandboxItem[];
187	}) {
188	  const navigate = useNavigate();
189	  const [filter, setFilter] = useState<ConnectorFilter>("all");
190	
191	  const items = useMemo(() => {
192	    const groupMap = new Map(groups.map((g) => [g.connector_key, g] as const));
193	    const defMap = new Map<string, ConnectorDefinitionItem>();
194	    for (const def of installedDefs) defMap.set(def.key, def);
195	    for (const group of groups) {
196	      if (!defMap.has(group.connector_key)) {
197	        defMap.set(group.connector_key, {
198	          key: group.connector_key,
199	          name: group.connector_name ?? group.connector_key,
200	          description: null,
201	          version: "",
202	          auth_schema: null,
203	          feeds_schema: null,
204	          actions_schema: null,
205	          options_schema: null,
206	          status: "active",
207	          login_enabled: false,
208	          favicon_domain: group.favicon_domain,
209	          facets: group.facets,
210	        } as ConnectorDefinitionItem & { facets?: ConnectionFacets });
211	      }
212	    }
213	
214	    // Model-provider rows, synthesized from `inference_providers`. They carry
215	    // no group, no auth profiles, and no setup state — a provider without a
216	    // working key surfaces that as its own `status`, not as "needs setup".
217	    const providerItems = buildInferenceConnectorRows(inferenceProviders).map(
218	      (row) => ({
219	        connector: row.connector,
220	        group: undefined,
221	        profileCounts: {
222	          env: 0,
223	          oauth_app: 0,
224	          oauth_account: 0,
225	          browser_session: 0,
226	        },
227	        facets: row.facets,
228	        needsSetup: false,
229	        provider: row.provider as InferenceProviderItem | undefined,
230	        sandbox: undefined as SandboxItem | undefined,
231	      })
232	    );
233	
234	    // Remote-sandbox rows, synthesized from `/sandboxes`. A missing vault
235	    // credential is `status: error` (and needsSetup), not a separate surface.
236	    const sandboxItems = buildSandboxConnectorRows(sandboxes).map((row) => ({
237	      connector: row.connector,
238	      group: undefined,
239	      profileCounts: {
240	        env: 0,
241	        oauth_app: 0,
242	        oauth_account: 0,
243	        browser_session: 0,
244	      },
245	      facets: row.facets,
246	      needsSetup: !row.sandbox.connected,
247	      provider: undefined as InferenceProviderItem | undefined,
248	      sandbox: row.sandbox,
249	    }));
250	
251	    const connectorItems = Array.from(defMap.values())
252	      // The list is the org's INSTALLED connectors only — the browsable catalog
253	      // of not-yet-added connectors lives on the "Add connector" page
254	      // (/connectors/create). A connector belongs here once it's installed or
255	      // has at least one connection (a group). Uninstalled catalog entries are
256	      // reachable via "Add connector", so nothing is stranded.
257	      .filter(
258	        (connector) =>
259	          connector.installed ||
260	          (groupMap.get(connector.key)?.connection_count ?? 0) > 0
261	      )
262	      .map((connector) => {
263	        const group = groupMap.get(connector.key);
264	        const methods = getAuthMethods(connector.auth_schema);
265	        const profileCounts = authProfiles.reduce(
266	          (acc, profile) => {
267	            if (profile.connector_key !== connector.key) return acc;
268	            acc[profile.profile_kind] += 1;
269	            return acc;
270	          },
271	          { env: 0, oauth_app: 0, oauth_account: 0, browser_session: 0 }
272	        );
273	        const facets = deriveConnectorFacets(connector, group);
274	        const needsSetup = connectorNeedsSetup(
275	          connector,
276	          group,
277	          methods,
278	          profileCounts
279	        );
280	        return {
281	          connector,
282	          group,
283	          profileCounts,
284	          facets,
285	          needsSetup,
286	          provider: undefined as InferenceProviderItem | undefined,
287	          sandbox: undefined as SandboxItem | undefined,
288	        };
289	      });
290	
291	    return [...connectorItems, ...providerItems, ...sandboxItems]
292	      .filter((item) => connectorMatchesFilter(item, filter))
293	      .sort((a, b) => {
294	        // Every item here is installed or has connections, so "needs setup"
295	        // (installed-but-unconfigured) floats to the top as the actionable set.
296	        if (a.needsSetup && !b.needsSetup) return -1;
297	        if (!a.needsSetup && b.needsSetup) return 1;
298	        return a.connector.name.localeCompare(b.connector.name);
299	      });
300	  }, [
301	    authProfiles,
302	    filter,
303	    groups,
304	    installedDefs,
305	    inferenceProviders,
306	    sandboxes,
307	  ]);
308	
309	  const addConnector = (
310	    <Button asChild variant="outline" size="sm" className="h-8 shrink-0 text-xs">
311	      <Link to="/$owner/connectors/create" params={{ owner: ownerSlug }}>
312	        <Plus className="mr-1.5 h-3.5 w-3.5" />
313	        Add connector
314	      </Link>
315	    </Button>
316	  );
317	
318	  // Reserved-footprint skeleton — the same bordered row list the loaded page
319	  // uses, so nothing reflows when the groups land.
320	  if (isContentLoading) {
321	    return (
322	      <div className="space-y-4">
323	        <div className="flex justify-end">{addConnector}</div>
324	        <div
325	          className="overflow-hidden rounded-lg border"
326	          role="status"
327	          aria-label="Loading connectors"
328	        >
329	          {Array.from({ length: 6 }).map((_, i) => (
330	            <div
331	              // biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
332	              key={i}
333	              className={`flex items-center gap-3 px-3 py-2.5 ${
334	                i === 5 ? "" : "border-b"
335	              }`}
336	            >
337	              <Skeleton className="h-7 w-7 shrink-0 rounded-md" />
338	              <div className="min-w-0 flex-1 space-y-1.5">
339	                <Skeleton className="h-4 w-40" />
340	                <Skeleton className="h-3 w-24" />
341	              </div>
342	            </div>
343	          ))}
344	        </div>
345	      </div>
346	    );
347	  }
348	
349	  if (items.length === 0 && filter === "all") {
350	    return (
351	      <div className="space-y-4">
352	        <div className="flex justify-end">{addConnector}</div>
353	        <TabEmptyState
354	          icon={OWNER_SECTIONS.connectors.icon}
355	          title="No connectors added yet"
356	          description="Add a connector from the catalog — data, chat, inference, or a sandbox runtime."
357	          actionLabel="Add connector"
358	          onAction={() =>
359	            navigate({
360	              to: "/$owner/connectors/create",
361	              params: { owner: ownerSlug },
362	            })
363	          }
364	        />
365	      </div>
366	    );
367	  }
368	
369	  return (
370	    <div className="space-y-4">
371	      {/* Lede row matches InfraTabScaffold: short description left, Add right.
372	          Filters sit on their own row below so the many chips can wrap without
373	          colliding with the button. */}
374	      <div className="flex flex-wrap items-center justify-between gap-3">
375	        <p className="text-sm text-muted-foreground">
376	          Tools your agents use for data, conversations, actions, inference, and
377	          remote runtimes. Sandbox providers are kinds in Add connector (Runtime
378	          filter); device-bound connectors show under On device.
379	        </p>
380	        {addConnector}
381	      </div>
382	      <div className="flex flex-wrap items-center gap-1.5">
383	        {FILTERS.map((key) => (
384	          <Button
385	            key={key}
386	            type="button"
387	            variant={filter === key ? "secondary" : "ghost"}
388	            size="sm"
389	            className="h-7 px-2 text-xs"
390	            onClick={() => setFilter(key)}
391	          >
392	            {CONNECTOR_FILTER_LABELS[key]}
393	          </Button>
394	        ))}
395	      </div>
396	
397	      {items.length === 0 ? (
398	        <TabEmptyState
399	          icon={OWNER_SECTIONS.connectors.icon}
400	          title="No connectors match this filter"
401	          description="Try another capability or auth filter."
402	          secondaryActionLabel="Show all"
403	          secondaryOnAction={() => setFilter("all")}
404	        />
405	      ) : (
406	        <div className="overflow-hidden rounded-lg border">
407	          {items.map(
408	            (
409	              {
410	                connector,
411	                group,
412	                facets,
413	                profileCounts,
414	                needsSetup,
415	                provider,
416	                sandbox,
417	              },
418	              idx
419	            ) => {
420	              const defsMap = new Map(
421	                installedDefs.map((d) => [d.key, d] as const)
422	              );
423	              // Provider rows have no connector definition; their icon joins
424	              // the inference catalog by `kind` (the provider's catalog
425	              // identity). Custom kinds miss the catalog and degrade to the
426	              // letter-mark. Sandbox rows use the sandbox name only.
427	              const display = resolveConnectorDisplay(connector.key, defsMap, {
428	                name: connector.name,
429	                iconUrl: provider
430	                  ? inferenceCatalog.find((c) => c.slug === provider.kind)
431	                      ?.iconUrl
432	                  : undefined,
433	                faviconDomain:
434	                  connector.favicon_domain ??
435	                  group?.favicon_domain ??
436	                  // Sandboxes have no definition and no catalog to join, so
437	                  // their logo comes from the provider kind's domain.
438	                  (sandbox
439	                    ? sandboxProviderFaviconDomain(sandbox.providerKind)
440	                    : undefined),
441	              });
442	              const accountCount =
443	                profileCounts.oauth_account + profileCounts.browser_session;
444	              const connectionCount = group?.connection_count ?? 0;
445	              // Provider / sandbox rows have no connections/accounts to count —
446	              // their meta is the credential state that actually matters.
447	              const meta = provider
448	                ? [provider.isDefault ? "Default" : null, provider.status]
449	                    .filter(Boolean)
450	                    .join(" · ")
451	                : sandbox
452	                  ? [
453	                      sandbox.providerKind,
454	                      sandbox.connected ? "Connected" : "No credential",
455	                    ].join(" · ")
456	                  : [
457	                      `${connectionCount} ${
458	                        connectionCount === 1 ? "connection" : "connections"
459	                      }`,
460	                      accountCount > 0
461	                        ? `${accountCount} ${accountCount === 1 ? "account" : "accounts"}`
462	                        : null,
463	                      profileCounts.oauth_app > 0
464	                        ? `${profileCounts.oauth_app} OAuth app${
465	                            profileCounts.oauth_app === 1 ? "" : "s"
466	                          }`
467	                        : null,
468	                    ]
469	                      .filter(Boolean)
470	                      .join(" · ");
471	              const rowClassName = `flex items-center gap-3 px-3 py-2.5 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground ${
472	                idx === items.length - 1 ? "" : "border-b"
473	              }`;
474	              // Prefixed keys (inference / sandbox) route to the same detail
475	              // path; the detail page branches on the prefix.
476	              const rowBody = (
477	                <>
478	                  <ConnectorMark
479	                    icon={display.icon}
480	                    iconUrl={display.iconUrl}
481	                    name={display.name}
482	                    faviconDomain={display.faviconDomain}
483	                    className="h-7 w-7 shrink-0 rounded-md text-[10px]"
484	                  />
485	                  <div className="min-w-0 flex-1">
486	                    <div className="flex flex-wrap items-center gap-2">
487	                      <span className="truncate text-sm font-medium">
488	                        {display.name}
489	                      </span>
490	                      <FacetChips facets={facets} />
491	                    </div>
492	                    <p className="truncate text-xs text-muted-foreground">
493	                      {meta}
494	                    </p>
495	                  </div>
496	                  {needsSetup ? (
497	                    <Badge variant="secondary" className="shrink-0 text-[10px]">
498	                      Needs setup
499	                    </Badge>
500	                  ) : null}
501	                </>
502	              );
503	
504	              return (
505	                <Link
506	                  key={connector.key}
507	                  to="/$owner/connectors/$connectorKey"
508	                  params={{ owner: ownerSlug, connectorKey: connector.key }}
509	                  className={rowClassName}
510	                >
511	                  {rowBody}
512	                </Link>
513	              );
514	            }
515	          )}
516	        </div>
517	      )}
518	    </div>
519	  );
520	}
521	
522	function connectorNeedsSetup(
523	  connector: ConnectorDefinitionItem,
524	  group: ConnectionConnectorGroup | undefined,
525	  methods: ReturnType<typeof getAuthMethods>,
526	  profileCounts: Record<
527	    "env" | "oauth_app" | "oauth_account" | "browser_session",
528	    number
529	  >
530	): boolean {
531	  // "Needs setup" means an INSTALLED connector is missing a required binding
532	  // (credentials / OAuth app / app install / device) — NOT merely "not added".
533	  // Uninstalled catalog entries no longer render in this list, so being
534	  // uninstalled is not a setup state here.
535	  if (
536	    methods.some((m) => m.type === "oauth") &&
537	    profileCounts.oauth_app === 0
538	  ) {
539	    return true;
540	  }
541	  if (methods.some((m) => m.type === "env_keys") && profileCounts.env === 0) {
542	    return true;
543	  }
544	  if (methods.some((m) => m.type === "app_installation") && !group) {
545	    return true;
546	  }
547	  // Device-bound connector (declares a required_capability) with no connection
548	  // yet: its runtime binding is unsatisfied. `!group` mirrors the app_install
549	  // branch above — resolveDeviceBinding guarantees no connection exists for
550	  // these without a valid device, so a group implies the binding is done.
551	  if (connector.required_capability && !group) {
552	    return true;
553	  }
554	  return false;
555	}
