import { createFileRoute, redirect } from "@tanstack/react-router";

/**
 * Activity is the Memory Events stream, not a separate page. The sidebar
 * "Activity" row links to `/memory` (events default). Keep this route as a
 * redirect so any early `/activity` links still resolve.
 */
export const Route = createFileRoute("/$owner/activity")({
	beforeLoad: ({ params }) => {
		throw redirect({
			to: "/$owner/memory",
			params: { owner: params.owner },
			search: {},
			replace: true,
		});
	},
});

