						<div className={`h-2.5 shrink-0 rounded bg-muted/40 ${row.meta}`} />
					</div>
				))}
			</div>
			<div className="absolute inset-0 flex items-center justify-center px-4">
				<div className="max-w-md rounded-xl border bg-background/85 px-6 backdrop-blur-sm">
					<TabEmptyState
						icon={Inbox}
						title="No activity yet"
						description={description}
						actionLabel={showActions ? "Add connector" : undefined}
						onAction={
							showActions
								? () =>
										void navigate({
											to: "/$owner/connectors",
											params: { owner: ownerSlug },
										})
								: undefined
						}
					/>
				</div>
			</div>
		</div>
	);
}

