48		watcherSourceLink,
49		type DrillSourceLink,
50	} from "@/lib/memory-drill-links";
51	import {
52		resolveConnectionFilterLabel,
53		resolveFeedFilterLabel,
54	} from "@/lib/event-filter-labels";
55	import {
56		applyEventTabDefaults,
57		type ClassificationFilters,
58		hasActiveFilters as checkActiveFilters,
59		EVENT_FILTER_KEYS,
60		isDateFeedMode,
61		type PartialEventFilters,
