64	} from "@/lib/event-filters";
65	import { formatShortDate, formatTimeAgo } from "@/lib/format-utils";
66	import { EntityLinkCell } from "../entity-link-cell";
67	import { TabEmptyState, TabErrorState } from "../tab-states";
68	import { EventCard } from "./event-card";
69	import { DrillFilterBanner } from "./drill-filter-banner";
70	import { EventsFilterBar } from "./events-filter-bar";
71	import { EventsTimeline } from "./events-timeline";
72	import {
73		collapseSupersedeChains,
74		groupContentByThread,
75		mergeEventTabFilters,
76	} from "./navigation";
77	
78	interface EventsTabProps {
79		/**
80		 * Org id when workspace is resolved. `null` during the cold-cache
81		 * workspace-loading window (org-wide events landing only). When null,
82		 * the filter-bar chrome still renders so the user sees the search +
83		 * tabs from the first frame; the data queries stay disabled until
84		 * workspace lands.
85		 */
86		organizationId: string | null;
87		ownerSlug?: string; // Required for org-wide mode drill-down links
88		entityId?: number; // Scope via prop (legacy) or the ?entity_id= URL filter
89		/** Memory page filters sources in the sidebar rail. */
90		hideSourceFilter?: boolean;
91		/** Memory browse drill-down: force event queries to this entity type. */
92		scopedEntityTypes?: string[];
93	}
94	
95	interface ClassifierEntry {
96		slug: string;
97		name: string;
98		values: string[];
99		parentSlug: string | null;
100		valuesByParentValue: Record<string, string[]>;
101	}
102	
103	interface BehaviorClassifierGroup {
104		behaviorName: string | null;
105		classifiers: ClassifierEntry[];
106	}
107	
108	/**
109	 * One node on the vertical timeline rail. The left gutter holds the dot and a
110	 * relative timestamp (absolute on hover); a connecting line runs the full
111	 * height and is hidden on the last row via `isLast` so the rail doesn't dangle
112	 * past the final event. Content (the borderless EventCard) sits on the right.
113	 */
114	function TimelineRow({
115		occurredAt,
116		isLast,
117		children,
118	}: {
119		occurredAt: string | Date | number | null | undefined;
120		isLast?: boolean;
121		children: React.ReactNode;
122	}) {
123		return (
124			<div className="relative flex gap-4 pb-6">
125				{/* Rail: dot + connecting line. The line spans the full row height so
126				    adjacent nodes read as one continuous timeline; `isLast` drops it on
127				    the final row so the rail doesn't dangle past the last event. */}
128				<div className="relative flex w-2.5 shrink-0 justify-center">
129					{!isLast && (
130						<div
131							className="absolute top-1 bottom-[-1.5rem] left-1/2 w-px -translate-x-1/2 bg-border"
132							aria-hidden
133						/>
134					)}
135					<div className="relative z-10 mt-1 h-2.5 w-2.5 rounded-full border-2 border-background bg-muted-foreground/60" />
136				</div>
137	
138				{/* Content column: timestamp header + event body */}
139				<div className="min-w-0 flex-1">
140					{occurredAt && (
141						<time
142							dateTime={new Date(occurredAt).toISOString()}
143							title={formatShortDate(occurredAt)}
144							className="mb-1 block text-xs leading-none text-muted-foreground"
145						>
146							{formatTimeAgo(occurredAt)}
147						</time>
148					)}
149					{children}
150				</div>
151			</div>
152		);
153	}
154	
155	export function EventsTab({
156		organizationId,
157		ownerSlug,
158		entityId,
159		hideSourceFilter = false,
160		scopedEntityTypes,
161	}: EventsTabProps) {
162		const { isAuthenticated, isReady } = useAuthState();
163		const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
164		const canManageWorkspace = isReady && isAuthenticated && isMember;
165		const canReadPublicWorkspace =
166			isReady && (!isAuthenticated || (!isOrgLoading && !isMember));
167	
168		const navigate = useNavigate();
169		const location = useLocation();
170		const scheduleScopeId = parseScheduleScope(location.search ?? {});
171	
172		const {
173			filters: urlFilters,
174			updateFilters: updateUrlFilters,
175			clearFilters: clearUrlFilters,
176		} = useTabFilters<PartialEventFilters>({
177			parse: parseEventFiltersFromUrl,
178			serialize: serializeEventFiltersToSearch,
179			filterKeys: EVENT_FILTER_KEYS,
180			merge: mergeEventTabFilters,
181		});
182	
183		// Local search state (for debouncing)
184		const [searchQuery, setSearchQuery] = useState(urlFilters.searchQuery || "");
185		const debouncedSearch = useDebounce(searchQuery, 1000);
186	
187		// Combine URL filters with debounced search
188		const filters = useMemo<PartialEventFilters>(
189			() =>
190				applyEventTabDefaults({
191					...urlFilters,
192					searchQuery: debouncedSearch.length >= 3 ? debouncedSearch : undefined,
193					...(scopedEntityTypes?.length
194						? { entityTypes: scopedEntityTypes }
195						: {}),
196				}),
197			[urlFilters, debouncedSearch, scopedEntityTypes],
198		);
199	
200		const updateFilters = updateUrlFilters;
201	
202		useEffect(() => {
203			const normalizedSearch =
204				debouncedSearch.length >= 3 ? debouncedSearch : undefined;
205			if ((urlFilters.searchQuery || undefined) === normalizedSearch) {
206				return;
207			}
208			updateUrlFilters({ searchQuery: normalizedSearch });
209		}, [debouncedSearch, updateUrlFilters, urlFilters.searchQuery]);
210	
211		const clearFilters = () => {
212			setSearchQuery("");
213			clearUrlFilters();
214		};
215	
216		const hasFilters = useMemo(
217			() =>
218				checkActiveFilters(
219					applyEventTabDefaults({
220						...urlFilters,
221						searchQuery:
222							debouncedSearch.length >= 3 ? debouncedSearch : undefined,
223					}),
224				),
225			[urlFilters, debouncedSearch],
226		);
227	
228		// Entity scope comes from either the prop (when embedded as an entity tab) or
229		// the URL drill-down filter — the entity page's "See memory" deep-links into
230		// the org-wide Memory page with ?entity_id=…. Both paths scope identically.
231		const effectiveEntityId = entityId ?? filters.entityId ?? undefined;
232		const isOrgWide = effectiveEntityId === undefined;
233	
234		// Fetch data — gate every auth/public fork on `isReady` so the bootstrap
235		// window (isAuthenticated=false, isReady=false) doesn't fire the public
236		// query and 404 against a private org before auth resolves.
237		const { data: connectorDefinitions = [] } = useConnectorDefinitions(
238			isReady && canManageWorkspace ? organizationId : null,
239		);
240		const { data: publicConnectorDefinitions = [] } =
241			usePublicConnectorDefinitions(canReadPublicWorkspace ? ownerSlug : null);
242		const effectiveConnectorDefinitions = canManageWorkspace
243			? connectorDefinitions
244			: publicConnectorDefinitions;
245	
246		const memoryConnectorGroups = useOptionalMemoryConnectorGroups();
247		const connectionFilterIds = filters.connectionIds;
248		const hasConnectionFilter = (connectionFilterIds?.length ?? 0) > 0;
249		const { data: filteredConnections = [] } = useConnections(
250			isReady && canManageWorkspace ? (organizationId ?? "") : "",
251			{
252				connectionIds: connectionFilterIds ?? undefined,
253				enabled:
254					!memoryConnectorGroups &&
255					isReady &&
256					canManageWorkspace &&
257					hasConnectionFilter,
258			},
259		);
260		const feedFilterIds = filters.feedIds;
261		const hasFeedFilter = (feedFilterIds?.length ?? 0) > 0;
262		const { data: workspaceFeeds = [] } = useAllFeeds(
263			isReady && canManageWorkspace ? organizationId : null,
264			{
265				feedIds: feedFilterIds ?? undefined,
266				enabled: isReady && canManageWorkspace && hasFeedFilter,
267			},
268		);
269	
270		const connectionLabelSources = useMemo(() => {
271			if (memoryConnectorGroups) {
272				return memoryConnectorGroups.groups.flatMap((group) =>
273					group.connections.map((connection) => ({
274						id: connection.id,
275						display_name: connection.display_name,
276						connector_name: group.connector_name,
277						connector_key: group.connector_key,
278					})),
279				);
280			}
281			return filteredConnections;
282		}, [filteredConnections, memoryConnectorGroups]);
283	
284		const connectionFilterLabel = useMemo(
285			() =>
286				hasConnectionFilter
287					? resolveConnectionFilterLabel(
288							connectionFilterIds ?? [],
289							connectionLabelSources,
290						)
291					: null,
292			[connectionFilterIds, connectionLabelSources, hasConnectionFilter],
293		);
294	
295		const feedFilterLabel = useMemo(
296			() =>
297				hasFeedFilter
298					? resolveFeedFilterLabel(feedFilterIds ?? [], workspaceFeeds)
299					: null,
300			[feedFilterIds, hasFeedFilter, workspaceFeeds],
301		);
302	
303		const agentFilterId = filters.agentId;
304		const { data: workspaceAgents = [] } = useAgents({
305			enabled: isReady && !!agentFilterId,
306		});
307		const agentFilterLabel = useMemo(() => {
308			if (!agentFilterId || filters.watcherId != null || scheduleScopeId) {
309				return null;
310			}
311			if ((filters.platforms?.length ?? 0) > 0) return null;
312			const agent = workspaceAgents.find((item) => item.agentId === agentFilterId);
313			return agent ? `From agent ${agent.name}` : `From agent ${agentFilterId}`;
314		}, [
315			agentFilterId,
316			filters.platforms,
317			filters.watcherId,
318			scheduleScopeId,
319			workspaceAgents,
320		]);
321	
322		const watcherFilterId = filters.watcherId;
323		const { data: scopedWatchers = [] } = useAgentWatchersList(agentFilterId ?? undefined, {
324			includeDetails: false,
325		});
326		const watcherFilterLabel = useMemo(() => {
327			if (watcherFilterId == null) return null;
328			const match = scopedWatchers.find(
329				(w) => String(w.behavior_id) === String(watcherFilterId),
330			);
331			return match
332				? `From watch “${match.name}”`
333				: `From Behavior #${watcherFilterId}`;
334		}, [scopedWatchers, watcherFilterId]);
335	
336		const { data: scopedSchedules = [] } = useSchedules(agentFilterId ?? undefined);
337		const scheduleFilterLabel = useMemo(() => {
338			if (!scheduleScopeId || !agentFilterId) return null;
339			const match = scopedSchedules.find((s) => s.id === scheduleScopeId);
340			return match?.description?.trim()
341				? `From schedule “${match.description.trim()}”`
342				: "From scheduled task";
343		}, [agentFilterId, scheduleScopeId, scopedSchedules]);
344	
345		const listenFilterLabel = useMemo(() => {
346			if (
347				!agentFilterId ||
348				watcherFilterId != null ||
349				scheduleScopeId ||
350				(filters.platforms?.length ?? 0) === 0
351			) {
352				return null;
353			}
354			const platform = filters.platforms?.[0];
355			return platform ? `From ${platform} listen` : null;
356		}, [
357			agentFilterId,
358			filters.platforms,
359			scheduleScopeId,
360			watcherFilterId,
361		]);
362	
363		const drillSourceLinks = useMemo(() => {
364			if (!ownerSlug) return {};
365			const links: Record<string, DrillSourceLink | undefined> = {};
366	
367			if (hasFeedFilter && feedFilterIds?.length === 1) {
368				const feed = workspaceFeeds.find((f) => f.id === feedFilterIds[0]);
369				if (feed) links.feedIds = feedSourceLink(ownerSlug, feed);
370			}
371	
372			if (hasConnectionFilter && connectionFilterIds?.length === 1) {
373				const connection = connectionLabelSources.find(
374					(c) => c.id === connectionFilterIds[0],
375				);
376				if (connection?.connector_key) {
377					links.connectionIds = connectionSourceLink(ownerSlug, {
378						id: connection.id,
379						connector_key: connection.connector_key,
380					});
381				}
382			}
383	
384			if (
385				agentFilterId &&
386				watcherFilterId == null &&
387				!scheduleScopeId &&
388				(filters.platforms?.length ?? 0) === 0
389			) {
390				links.agentId = agentFeedsSourceLink(ownerSlug, agentFilterId);
391			}
392	
393			if (agentFilterId && watcherFilterId != null) {
394				links.watcherId = watcherSourceLink(
395					ownerSlug,
396					agentFilterId,
397					String(watcherFilterId),
398				);
399			}
400	
401			if (agentFilterId && scheduleScopeId) {
402				links.schedule = scheduleSourceLink(
403					ownerSlug,
404					agentFilterId,
405					scheduleScopeId,
406				);
407			}
408	
409			if (listenFilterLabel && agentFilterId) {
410				links.listen = agentFeedsSourceLink(ownerSlug, agentFilterId);
411			}
412	
413			return links;
414		}, [
415			agentFilterId,
416			connectionFilterIds,
417			connectionLabelSources,
418			feedFilterIds,
419			hasConnectionFilter,
420			hasFeedFilter,
421			filters.platforms,
422			listenFilterLabel,
423			ownerSlug,
424			scheduleScopeId,
425			watcherFilterId,
426			workspaceFeeds,
427		]);
428	
429		// Classifiers only available when entity is specified
430		const { data: classifiersData } = useEntityClassifiers(
431			isReady && canManageWorkspace ? organizationId : null,
432			isOrgWide ? undefined : effectiveEntityId,
433		);
434		const { data: publicClassifiersData } = usePublicEntityClassifiers(
435			canReadPublicWorkspace && !isOrgWide ? ownerSlug : null,
436			isOrgWide ? undefined : effectiveEntityId,
437		);
438		const effectiveClassifiersData = canManageWorkspace
439			? classifiersData
440			: publicClassifiersData;
441		const classifierGroups = useMemo<BehaviorClassifierGroup[]>(() => {
442			const groupMap = new Map<string, BehaviorClassifierGroup>();
443			for (const c of effectiveClassifiersData || []) {
444				const key = c.behavior_name ?? "__global__";
445				if (!groupMap.has(key)) {
446					groupMap.set(key, {
447						behaviorName: c.behavior_name ?? null,
448						classifiers: [],
449					});
450				}
451				const group = groupMap.get(key)!;
452	
453				const attrValues = c.attribute_values || {};
454				const values = Object.keys(attrValues);
455	
456				// Detect parent-child from attribute_values.parent field
457				let parentSlug: string | null = null;
458				const valuesByParentValue: Record<string, string[]> = {};
459	
460				for (const [val, config] of Object.entries(attrValues)) {
461					if (config.parent) {
462						for (const [pSlug, pValue] of Object.entries(config.parent)) {
463							parentSlug = pSlug;
464							if (!valuesByParentValue[pValue]) {
465								valuesByParentValue[pValue] = [];
466							}
467							valuesByParentValue[pValue].push(val);
468						}
469					}
470				}
471	
472				const existing = group.classifiers.find((gc) => gc.slug === c.slug);
473				if (existing) {
474					const merged = new Set([...existing.values, ...values]);
475					existing.values = [...merged];
476					for (const [pVal, cVals] of Object.entries(valuesByParentValue)) {
477						if (!existing.valuesByParentValue[pVal]) {
478							existing.valuesByParentValue[pVal] = [];
479						}
480						const mergedVals = new Set([
481							...existing.valuesByParentValue[pVal],
482							...cVals,
483						]);
484						existing.valuesByParentValue[pVal] = [...mergedVals];
485					}
486					if (parentSlug) existing.parentSlug = parentSlug;
487				} else {
488					group.classifiers.push({
489						slug: c.slug,
490						name: c.name,
491						values,
492						parentSlug,
493						valuesByParentValue,
494					});
495				}
496			}
497	
498			// Sort: parents first, then children
499			for (const group of groupMap.values()) {
500				group.classifiers.sort((a, b) => {
501					if (a.parentSlug === null && b.parentSlug !== null) return -1;
502					if (a.parentSlug !== null && b.parentSlug === null) return 1;
503					return 0;
504				});
505			}
506	
507			return [...groupMap.values()];
508		}, [effectiveClassifiersData]);
509	
510		const connectors = useMemo<ConnectorSelectorItem[]>(() => {
511			const definitionsByKey = new Map(
512				effectiveConnectorDefinitions.map((definition) => [
513					definition.key,
514					definition,
515				]),
516			);
517			const seenKeys = new Set<string>(definitionsByKey.keys());
518	
519			return [...seenKeys]
520				.map((key) => {
521					const definition = definitionsByKey.get(key);
522					return {
523						key,
524						name: definition?.name || key,
525						description: definition?.description,
526						icon: definition?.icon,
527						faviconDomain: extractOAuthDomain(definition?.auth_schema),
528					};
529				})
530				.sort((left, right) => left.name.localeCompare(right.name));
531		}, [effectiveConnectorDefinitions]);
532	
533		// Fetch events with infinite scroll — gate by auth state so private orgs
