1148										{/* Entity link in org-wide mode */}
1149										{isOrgWide && ownerSlug && mainContent.entity_name && (
1150											<div className="mb-2">
1151												<EntityLinkCell
1152													ownerSlug={ownerSlug}
1153													entity={{
1154														entityId: mainContent.entity_ids?.[0],
1155														entityName: mainContent.entity_name,
1156														entityType: mainContent.entity_type || "brand",
1157														entitySlug: mainContent.entity_slug || "",
1158													}}
1159													tab="events"
1160												/>
1161											</div>
1162										)}
1163	
1164										{/* Main event card */}
1165										<EventCard
1166											content={mainContent}
1167											showParentContext={
1168												isOrphanedThread && !!mainContent.parent_context
1169											}
1170										/>
1171	
1172										{/* Earlier states — for a run, its lifecycle (pending →
1173										    executing → completed) plus the "needs approval"
1174										    notification, all folded here and labelled by run so the
1175										    node reads as one run's history. Collapsed by default. */}
1176										{history.length > 0 && (
1177											<Collapsible open={historyOpen}>
1178												<CollapsibleTrigger asChild>
1179													<Button
1180														variant="ghost"
1181														size="sm"
1182														className="mt-1 h-7 gap-1 text-xs text-muted-foreground"
1183														onClick={() => toggleHistory(rootId)}
1184													>
1185														<History className="h-3.5 w-3.5" />
1186														{historyOpen ? (
1187															<>
1188																<ChevronUp className="h-3.5 w-3.5" />
1189																Hide {runId != null ? `run #${runId} ` : ""}
1190																history
1191															</>
1192														) : (
1193															<>
1194																<ChevronDown className="h-3.5 w-3.5" />
1195																{runId != null
1196																	? `Run #${runId} · ${
1197																			history.length === 1
1198																				? "1 earlier step"
1199																				: `${history.length} earlier steps`
1200																		}`
1201																	: history.length === 1
1202																		? "1 earlier state"
1203																		: `${history.length} earlier states`}
1204															</>
1205														)}
1206													</Button>
1207												</CollapsibleTrigger>
1208												<CollapsibleContent className="mt-2 space-y-3 border-l-2 border-l-muted pl-4">
1209													{history.map((prev) => (
1210														<div key={prev.id}>
1211															<time
1212																dateTime={new Date(
1213																	prev.occurred_at,
1214																).toISOString()}
1215																title={formatShortDate(prev.occurred_at)}
1216																className="mb-1 block text-xs text-muted-foreground"
1217															>
1218																{formatTimeAgo(prev.occurred_at)}
1219															</time>
1220															<EventCard content={prev} />
1221														</div>
1222													))}
1223												</CollapsibleContent>
1224											</Collapsible>
1225										)}
1226	
1227										{/* Thread replies */}
1228										{hasReplies && (
1229											<Collapsible open={isExpanded}>
1230												<CollapsibleTrigger asChild>
1231													<Button
1232														variant="ghost"
1233														size="sm"
1234														className="mt-2 ml-6 gap-1"
1235														onClick={() => toggleThread(rootId)}
1236													>
1237														<MessageSquare className="h-3.5 w-3.5" />
1238														{isExpanded ? (
1239															<>
1240																<ChevronUp className="h-3.5 w-3.5" />
1241																Hide {group.replies.length} replies
1242															</>
1243														) : (
1244															<>
1245																<ChevronDown className="h-3.5 w-3.5" />
1246																Show {group.replies.length} replies
1247															</>
1248														)}
1249													</Button>
1250												</CollapsibleTrigger>
1251												<CollapsibleContent className="space-y-2 mt-2">
1252													{/* Shallow replies */}
1253													{shallowReplies.map((reply) => (
1254														<EventCard key={reply.id} content={reply} isReply />
1255													))}
1256	
1257													{/* Deep replies toggle */}
1258													{deepReplies.length > 0 && (
1259														<>
1260															<Button
1261																variant="ghost"
1262																size="sm"
1263																className="ml-12"
1264																onClick={() => toggleDeepReplies(rootId)}
1265															>
1266																{showingDeep ? (
1267																	<>Hide {deepReplies.length} nested replies</>
1268																) : (
1269																	<>Show {deepReplies.length} nested replies</>
1270																)}
1271															</Button>
1272															{showingDeep &&
1273																deepReplies.map((reply) => (
1274																	<EventCard
1275																		key={reply.id}
1276																		content={reply}
1277																		isReply
1278																	/>
1279																))}
1280														</>
1281													)}
1282												</CollapsibleContent>
1283											</Collapsible>
1284										)}
1285									</TimelineRow>
1286								);
1287							},
1288							)}
1289						</div>
1290					)}
1291	
1292					{/* Infinite scroll sentinel */}
1293					<div ref={sentinelRef} className="h-1" />
1294					{isFetchingNextPage && (
1295						<div className="flex justify-center py-4">
1296							<Spinner size="xl" className="text-muted-foreground" />
1297						</div>
1298					)}
