1297							</summary>
1298							<pre className="mt-1 rounded bg-green-50 p-2 font-mono dark:bg-green-950/30 overflow-auto max-h-32">
1299								{JSON.stringify(actionOutput, null, 2)}
1300							</pre>
1301						</details>
