1313						</p>
1314					</div>
1315				)}
1316	
1317				{/* Resolved state (shown after approve/reject) */}
1318				{resolved === "confirmed" && (
1319					<div className="rounded-md bg-blue-50 dark:bg-blue-950/30 p-3 text-sm">
