1445	/**
1446	 * A watcher run's first-class change-set card: the created/updated summary and a
1447	 * per-entity diff, shown on the run itself even when the changes were auto-applied
1448	 * (no approval). When the run has a window and produced pending proposals, offers
1449	 * a one-click Approve all / Reject with feedback (the batch + revision loop —
1450	 * rejecting feeds the reason back so the user can ask the agent to revise). The
1451	 * batch-reject feedback event renders the recorded reason instead.
1452	 */
1453	function RunChangeSetCard({ content }: { content: ContentItem }) {
1454		const metadata = (content.metadata || {}) as Record<string, unknown>;
1455		const kind = metadata.kind as string | undefined;
1456		const windowId =
1457			typeof metadata.window_id === "number" ? metadata.window_id : null;
1458		const watcherId =
1459			typeof metadata.window_id === "number" &&
1460			typeof metadata.watcher_id === "number"
1461				? metadata.watcher_id
1462				: typeof metadata.watcher_id === "number"
1463					? metadata.watcher_id
1464					: null;
1465		const { org } = useCurrentOrg();
1466		const ownerSlug = org?.slug;
1467		// Resolve the watcher so the card can name it (and link to its page) — a batch
1468		// card with no identity is impossible to tell apart from another run's card.
1469		const watcherDetail = useWatcherDetail(
1470			watcherId != null ? String(watcherId) : undefined,
1471			undefined,
1472			org?.id,
1473			{ includeVersions: false },
1474		);
1475		const watcher = watcherDetail.data?.behavior;
1476		const watcherName =
1477			watcher?.behavior_name ??
1478			(watcherId != null ? `Behavior ${watcherId}` : "A Behavior");
1479		const watcherAgentId = watcher?.agent_id ?? null;
1480		const approveBatch = useApproveBatch();
1481		const rejectBatch = useRejectBatch();
1482		const [showReject, setShowReject] = useState(false);
1483		const [reason, setReason] = useState("");
1484		const [resolved, setResolved] = useState<"approved" | "rejected" | null>(
1485			null,
1486		);
1487	
1488		// The batch-reject feedback record: show why the run's proposals were rejected.
1489		if (kind === "watcher_batch_reject") {
1490			const rejectReason = (metadata.reason as string | undefined) || undefined;
1491			return (
1492				<div className="rounded-md border border-destructive/40 bg-destructive/5 p-3">
1493					<div className="text-sm font-medium">Proposals rejected</div>
1494					{rejectReason && (
1495						<div className="mt-1 text-sm text-muted-foreground">
1496							{rejectReason}
1497						</div>
1498					)}
1499					<div className="mt-1 text-xs text-muted-foreground">
1500						Ask the agent to revise its proposals with this feedback.
1501					</div>
1502				</div>
1503			);
1504		}
1505	
1506		const changes = Array.isArray(metadata.changes)
1507			? (metadata.changes as ChangeSetEntry[])
1508			: [];
1509		const createdCount =
1510			typeof metadata.created_count === "number"
1511				? metadata.created_count
1512				: changes.filter((c) => c.kind === "created").length;
1513		const updatedCount =
1514			typeof metadata.updated_count === "number"
1515				? metadata.updated_count
1516				: changes.filter((c) => c.kind === "updated").length;
1517		const updatedChanges = changes.filter(
