1545					<div className="text-xs text-muted-foreground">
1546						{ownerSlug && watcherAgentId && watcherId != null ? (
1547							<Link
1548								to="/$owner/agents/$agentId/behaviors/$watcherId"
1549								params={{
1550									owner: ownerSlug,
1551									agentId: watcherAgentId,
1552									watcherId: String(watcherId),
1553								}}
1554								search={{ view: "definition", run_id: undefined }}
1555								className="font-medium text-foreground underline-offset-4 hover:underline"
1556							>
1557								{watcherName}
1558							</Link>
1559						) : (
1560							<span className="font-medium text-foreground">{watcherName}</span>
1561						)}
1562						{windowId != null && <span> · run window #{windowId}</span>}
1563						{pendingProposalCount != null && pendingProposalCount > 0 && (
1564							<span> · {pendingProposalCount} pending</span>
1565						)}
1566					</div>
1567				</div>
1568	
1569				{/* Per-entity diff for updates — auto-applied changes are shown too. */}
1570				{updatedChanges.length > 0 && (
1571					<div className="mt-3 space-y-2">
1572						{updatedChanges.map((change) => (
1573							<div key={change.entityId} className="space-y-1.5">
1574								<div className="text-xs font-medium text-muted-foreground">
1575									{change.name}
1576								</div>
1577								{Object.entries(change.applied).map(([field, diff]) => (
1578									<FieldChangeDiff
1579										key={field}
1580										label={field}
1581										before={diff.old}
1582										after={diff.new}
1583									/>
1584								))}
1585							</div>
1586						))}
1587					</div>
1588				)}
1589	
1590				{/* Batch controls: approve-all / reject-with-feedback for the run's window.
1591				    Only while proposals remain pending (server-derived, refresh-safe) and
1592				    not already resolved in this session. */}
1593				{windowId != null && resolved == null && hasPendingProposals && (
1594					<div className="mt-3 border-t border-border/70 pt-3">
1595						{!showReject ? (
1596							<div className="flex items-center gap-2">
1597								<Button
1598									size="sm"
1599									className="h-7 text-xs"
1600									onClick={() =>
1601										approveBatch.mutate(
1602											{ window_id: windowId },
1603											{ onSuccess: () => setResolved("approved") },
1604										)
1605									}
1606									disabled={approveBatch.isPending || rejectBatch.isPending}
1607								>
1608									{approveBatch.isPending && (
1609										<Spinner size="sm" className="mr-1" />
1610									)}
1611									Approve all proposals
1612								</Button>
1613								<Button
1614									size="sm"
1615									variant="outline"
1616									className="h-7 text-xs"
1617									onClick={() => setShowReject(true)}
1618									disabled={approveBatch.isPending || rejectBatch.isPending}
1619								>
1620									Reject with feedback
1621								</Button>
1622							</div>
1623						) : (
1624							<div className="flex items-center gap-2 w-full">
1625								<input
1626									type="text"
1627									placeholder="What should the agent change?"
1628									value={reason}
1629									onChange={(e) => setReason(e.target.value)}
1630									className="h-7 text-xs border rounded px-2 flex-1 bg-background"
1631								/>
1632								<Button
1633									size="sm"
1634									variant="destructive"
1635									className="h-7 text-xs"
1636									onClick={() =>
1637										rejectBatch.mutate(
1638											{ window_id: windowId, reason: reason || undefined },
1639											{ onSuccess: () => setResolved("rejected") },
1640										)
1641									}
1642									disabled={rejectBatch.isPending}
1643								>
1644									{rejectBatch.isPending && (
1645										<Spinner size="sm" className="mr-1" />
1646									)}
1647									Reject all
1648								</Button>
1649								<Button
1650									size="sm"
1651									variant="ghost"
1652									className="h-7 text-xs px-2"
1653									onClick={() => {
1654										setShowReject(false);
1655										setReason("");
1656									}}
1657								>
1658									Cancel
1659								</Button>
1660							</div>
1661						)}
1662					</div>
1663				)}
1664				{resolved === "approved" && (
1665					<div className="mt-3 text-xs text-muted-foreground">
1666						All proposals approved.
1667					</div>
1668				)}
1669				{resolved === "rejected" && (
1670					<div className="mt-3 text-xs text-muted-foreground">
1671						Proposals rejected — ask the agent to revise them.
1672					</div>
1673				)}
1674				{/* Reviewed in a PRIOR session (server says no proposals remain pending):
1675				    show a resolved marker instead of nothing, so the card reads as done. */}
1676				{windowId != null && resolved == null && !hasPendingProposals && (
1677					<div className="mt-3 text-xs text-muted-foreground">
1678						All proposals reviewed.
1679					</div>
1680				)}
1681			</div>
1682		);
1683	}
1684	
