function MergeApprovalPanel({
	merge,
	status,
}: {
	merge: MergeDetails;
	status?: string;
}) {
	const { org } = useCurrentOrg();
	const winnerHref = entityHrefFor(org?.slug, {
		entityType: merge.winnerEntityType,
		entitySlug: merge.winnerSlug,
		parentEntityType: merge.winnerParentEntityType,
		parentSlug: merge.winnerParentSlug,
	});
	const loserCount = merge.losers.length;
	// A rejected proposal must not read like it happened: the records still
	// exist, nothing was tombstoned, and no identity moved. Anything not yet
	// terminal is still a proposal, so keep the forward-looking wording.
	const rejected = status === "rejected" || status === "failed";
	const applied = status === "completed";
	return (
		<div className="space-y-3">
			<div className="rounded-lg border border-border/70 overflow-hidden">
				<div className="grid gap-px bg-border/70 sm:grid-cols-2">
					<div className="bg-background p-3">
						<div className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
							{rejected ? "Would have kept" : "Kept"}
						</div>
						<div className="text-sm font-medium leading-relaxed">
							{merge.winnerName ? (
								winnerHref ? (
									<Link
										to={winnerHref as "/"}
										className="underline-offset-4 hover:underline"
									>
										{merge.winnerName}
									</Link>
								) : (
									merge.winnerName
								)
							) : (
								<span className="text-muted-foreground">Unknown</span>
							)}
						</div>
					</div>
					<div className="bg-background p-3">
						<div className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
							{rejected
								? loserCount > 1
									? `Kept separate (${loserCount})`
									: "Kept separate"
								: applied
									? loserCount > 1
										? `Merged away (${loserCount})`
										: "Merged away"
									: loserCount > 1
										? `To merge away (${loserCount})`
										: "To merge away"}
						</div>
						<div className="space-y-0.5 text-sm leading-relaxed">
							{loserCount > 0 ? (
								merge.losers.map((loser) => {
									// Losers link too: before approving something destructive a
									// reviewer most wants to open the record about to be
									// tombstoned and confirm it really is a duplicate.
									const loserHref = entityHrefFor(org?.slug, {
										entityType: loser.entityType,
										entitySlug: loser.slug,
										parentEntityType: loser.parentEntityType,
										parentSlug: loser.parentSlug,
									});
									// Strike-through reads as "this record is gone" — only true
									// once the merge actually applied.
									const struck = applied
										? "line-through decoration-muted-foreground/60"
										: "";
									return (
										<div key={loser.key} className="break-words">
											{loserHref ? (
												<Link
													to={loserHref as "/"}
													className={`${struck} underline-offset-4 hover:underline`}
												>
													{loser.name}
												</Link>
											) : (
												<span className={struck}>{loser.name}</span>
											)}
										</div>
									);
								})
							) : (
								<span className="text-muted-foreground">Unknown</span>
							)}
						</div>
					</div>
				</div>
			</div>
			{merge.matchEvidence.length > 0 && (
				<div className="rounded-lg bg-muted/40 px-3 py-2">
					<div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
						Match evidence
					</div>
					<div className="mt-1.5 flex flex-wrap gap-1.5">
						{merge.matchEvidence.map((evidence) => (
							<Badge
								key={`${evidence.kind}:${evidence.identifier}`}
								variant="outline"
								className="text-[10px] font-normal"
							>
								{formatLabel(evidence.kind)}: {evidence.identifier}
							</Badge>
						))}
					</div>
				</div>
			)}
		</div>
	);
}

function EntityChangeApprovalDetails({
	runId,
	details,
	status,
}: {
	runId?: number;
	details: EntityChangeDetails;
	status?: string;
}) {
	const isMerge = details.operation === "merge";
	return (
		<div className="space-y-3">
			<WatcherApprovalHeader runId={runId} details={details} />
			{isMerge && details.merge ? (
				<MergeApprovalPanel merge={details.merge} status={status} />
			) : (
				<>
					<EntityLinkPanel details={details} />
					<div className="rounded-md bg-muted/40 px-3 py-2">
						<div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
							Change
						</div>
						<div className="mt-1 text-sm leading-relaxed">
							{details.operation === "create"
								? "Create a new entity after approval."
								: "Delete this entity after approval."}
						</div>
					</div>
				</>
			)}
			{!isMerge && details.proposal && (
				<div className="rounded-md border border-border/70 p-3">
					<div className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
						Proposal
					</div>
					<pre className="overflow-x-auto whitespace-pre-wrap break-words text-xs leading-relaxed">
						{JSON.stringify(details.proposal, null, 2)}
					</pre>
				</div>
			)}
			{details.proposerRationale && (
				<div className="rounded-md bg-muted/40 px-3 py-2">
					<div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
						{details.attribution === "agent"
							? "The agent's reasoning"
							: "The Behavior's reasoning"}
					</div>
					<div className="mt-1 text-sm leading-relaxed">
						{details.proposerRationale}
					</div>
				</div>
			)}
			{details.reason && (
				<div className="rounded-md bg-muted/40 px-3 py-2">
					<div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
						{/* On merges this string explains why approval is required, not
						    why these records match — the structured match evidence is
						    shown separately above. Labelling it "Reasoning" reads as a
						    justification the text never gives. */}
						{isMerge ? "Why this needs approval" : "Reasoning"}
					</div>
					<div className="mt-1 text-sm leading-relaxed">{details.reason}</div>
				</div>
			)}
		</div>
	);
}

/** Human-readable browser-handoff block (prepare/verify) — reason, draft, status. */
function BrowserHandoffDetails({
