}) {
	return (
		<div className="space-y-2 rounded-md border border-border/70 bg-muted/30 p-3 text-sm">
			{summary.chips.length > 0 && (
				<div className="flex flex-wrap gap-1.5">
					{summary.chips.map((chip) => (
						<Badge
							key={chip}
							variant="outline"
							className="text-[10px] font-normal"
						>
							{chip}
