				<div className="rounded-md bg-background/80 px-2.5 py-2">
					<div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
						Why
					</div>
					<div className="mt-0.5 leading-relaxed">{summary.reason}</div>
				</div>
