function ActionApprovalCard({ content }: { content: ContentItem }) {
	const metadata = (content.metadata || {}) as Record<string, unknown>;
	const runId = metadata.run_id as number | undefined;
	const fieldChangeDetails = getEntityFieldChangeDetails(content, metadata);
	const entityChangeDetails = getEntityChangeDetails(content, metadata);
	const actionName =
		(fieldChangeDetails
			? formatFieldChangeAction(fieldChangeDetails)
			: entityChangeDetails
				? formatEntityChangeAction(entityChangeDetails)
				: undefined) ||
		(metadata.operation_name as string) ||
		(metadata.action_name as string) ||
		(content.title ? stripPendingSuffix(content.title) : undefined) ||
		"Action";
	const connectionName = metadata.connection_name as string | undefined;
	const actionKey =
		(metadata.operation_key as string | undefined) ||
		(metadata.action_key as string | undefined) ||
		null;

	const inputSchema =
		content.interaction_input_schema ||
		(metadata.input_schema as Record<string, unknown>) ||
		null;
	const actionInput = (content.interaction_input ||
		(metadata.action_input as Record<string, unknown>) ||
		(metadata.operation_input as Record<string, unknown>) ||
		{}) as Record<string, unknown>;
	const actionOutput =
		content.interaction_output ||
		(metadata.action_output as Record<string, unknown>) ||
		undefined;
	const handoffSummary = buildBrowserHandoffSummary(
		actionInput,
		actionOutput ?? null,
		actionKey,
	);
	const errorMessage =
		content.interaction_error ||
		(metadata.error_message as string) ||
		undefined;
	const status = mapInteractionStatus(
		content.interaction_status,
		metadata.status as string | undefined,
	);
	// Who decided this approval (stamped server-side at approve/reject time and
	// carried down the chain). Falls back to the id when the name didn't resolve.
	const reviewedByName =
		(metadata.reviewed_by_name as string | undefined) ||
		(metadata.reviewed_by_id as string | undefined) ||
		undefined;
	// The reviewer's rejection note; metadata.reason stays the proposer's rationale.
	const rejectReasonText =
		(metadata.reject_reason as string | undefined) || undefined;

	const approveRun = useApproveRun();
	const rejectRun = useRejectRun();
	const [formValues, setFormValues] =
		useState<Record<string, unknown>>(actionInput);
	useEffect(() => {
		setFormValues(actionInput);
	}, [actionInput]);
	const [resolved, setResolved] = useState<"confirmed" | "rejected" | null>(
		null,
	);
	const [showRejectInput, setShowRejectInput] = useState(false);
	const [rejectReason, setRejectReason] = useState("");

	const handleInputChange = useCallback((values: Record<string, unknown>) => {
		setFormValues(values);
	}, []);

	const isPending = status === "pending_approval";
	// A proposal that belongs to a watcher run window is decided by that run's
	// change-set card (Approve all / Reject with feedback), not per-proposal here.
	// Suppress this card's own buttons to avoid duplicate, easily-stale controls —
	// the card stays as read-only detail of the proposal.
	const partOfBatch = typeof metadata.window_id === "number";

	return (
		<div className="space-y-3">
			<div className="flex items-center gap-2">
				<Zap className="h-4 w-4 text-yellow-500" />
				<span className="font-medium">{actionName}</span>
				{connectionName && (
					<span className="text-xs text-muted-foreground">
						on {connectionName}
					</span>
				)}
				{status === "confirmed" && (
					<Badge
						variant="outline"
						className="text-blue-700 border-blue-300 bg-blue-50 dark:bg-blue-950/30 text-[10px]"
					>
						<Spinner size="xs" className="mr-1" />
						Executing
					</Badge>
				)}
				{status === "completed" && (
					<Badge
						variant="outline"
						className="text-green-700 border-green-300 bg-green-50 dark:bg-green-950/30 text-[10px]"
					>
						Completed
					</Badge>
				)}
				{status === "failed" && (
					<Badge
						variant="outline"
						className="text-red-700 border-red-300 bg-red-50 dark:bg-red-950/30 text-[10px]"
					>
						Failed
					</Badge>
				)}
				{status === "rejected" && (
					<Badge
						variant="outline"
						className="text-muted-foreground text-[10px]"
					>
						Rejected
					</Badge>
				)}
			</div>

			{!fieldChangeDetails &&
				!entityChangeDetails &&
				(content.author_name || reviewedByName) && (
					<div className="flex flex-wrap items-center gap-x-1.5 gap-y-0.5 text-xs text-muted-foreground">
						{content.author_name && (
							<span>Requested by {content.author_name}</span>
						)}
						{content.author_name && reviewedByName && <span>·</span>}
						{reviewedByName && (
							<span>
								{status === "rejected" ? "Rejected" : "Approved"} by{" "}
								<span className="font-medium text-foreground">
									{reviewedByName}
								</span>
							</span>
						)}
					</div>
				)}

			{fieldChangeDetails && (
				<EntityFieldChangeApprovalDetails
					runId={runId}
					details={fieldChangeDetails}
				/>
			)}
			{!fieldChangeDetails && entityChangeDetails && (
				<EntityChangeApprovalDetails
					runId={runId}
					details={entityChangeDetails}
					status={status}
				/>
			)}

			{/* Rejection reason — the reviewer's note, shown plainly. */}
			{status === "rejected" && rejectReasonText && (
				<div className="rounded-md bg-muted/50 p-2 text-xs text-muted-foreground">
					<span className="font-medium text-foreground">Reason:</span>{" "}
					{rejectReasonText}
				</div>
			)}

			{/* Browser handoff: reason / draft / status in plain language */}
			{handoffSummary && <BrowserHandoffDetails summary={handoffSummary} />}

			{/* Action form — editable when pending, read-only otherwise.
			    Handoff cards already show body/reason above; keep the form for
			    pending edits, collapse raw JSON when handoff summary is enough. */}
			{inputSchema && (
				<div>
					<p className="text-xs text-muted-foreground mb-1">
						{handoffSummary ? "Full input" : "Input"}
					</p>
					{isPending ? (
						<DynamicConnectorForm
							key={`action-${content.id}`}
							schema={inputSchema}
							initialValues={actionInput}
							onValuesChange={handleInputChange}
							fieldIdPrefix={`action-${content.id}-`}
						/>
					) : handoffSummary ? (
						<details className="text-xs">
							<summary className="cursor-pointer text-muted-foreground hover:text-foreground">
								Raw input
							</summary>
							<pre className="mt-1 bg-muted/50 rounded p-2 font-mono overflow-auto max-h-32">
								{JSON.stringify(actionInput, null, 2)}
							</pre>
						</details>
					) : (
						<pre className="text-xs bg-muted/50 rounded p-2 font-mono overflow-auto max-h-32">
							{JSON.stringify(actionInput, null, 2)}
						</pre>
					)}
				</div>
			)}

			{/* Output — handoff uses the summary; other actions keep JSON */}
			{status === "completed" &&
				actionOutput &&
				Object.keys(actionOutput).length > 0 &&
				!handoffSummary && (
					<div className="rounded-md bg-green-50 dark:bg-green-950/30 p-3 text-sm space-y-1">
						<div className="flex items-center gap-1.5 text-green-700 dark:text-green-400 font-medium">
							<CheckCircle2 className="h-3.5 w-3.5" />
							Output
						</div>
						<pre className="text-xs text-green-800 dark:text-green-300 font-mono whitespace-pre-wrap">
							{JSON.stringify(actionOutput, null, 2)}
						</pre>
					</div>
				)}
			{status === "completed" &&
				actionOutput &&
				Object.keys(actionOutput).length > 0 &&
				handoffSummary && (
					<details className="text-xs">
						<summary className="cursor-pointer text-muted-foreground hover:text-foreground">
							Raw output
						</summary>
						<pre className="mt-1 rounded bg-green-50 p-2 font-mono dark:bg-green-950/30 overflow-auto max-h-32">
							{JSON.stringify(actionOutput, null, 2)}
						</pre>
					</details>
				)}

			{/* Error */}
			{status === "failed" && errorMessage && (
				<div className="rounded-md bg-red-50 dark:bg-red-950/30 p-3 text-sm">
					<div className="flex items-center gap-1.5 text-red-700 dark:text-red-400 font-medium">
						<AlertCircle className="h-3.5 w-3.5" />
						Error
					</div>
					<p className="text-xs text-red-800 dark:text-red-300 font-mono mt-1">
						{errorMessage}
					</p>
				</div>
			)}

			{/* Resolved state (shown after approve/reject) */}
			{resolved === "confirmed" && (
				<div className="rounded-md bg-blue-50 dark:bg-blue-950/30 p-3 text-sm">
					<div className="flex items-center gap-1.5 text-blue-700 dark:text-blue-400 font-medium">
						<Spinner size="md" />
						Confirmed — executing...
					</div>
					<p className="text-xs text-blue-800 dark:text-blue-300 mt-1">
						The worker will execute this action shortly. Redirecting...
					</p>
				</div>
			)}
			{resolved === "rejected" && (
				<Badge variant="outline" className="text-muted-foreground text-xs">
					Rejected — redirecting...
				</Badge>
			)}

			{/* Part of a Behavior run: point to the run's change-set card for the
			    Approve-all / Reject-with-feedback decision instead of a per-proposal one. */}
			{isPending && !resolved && partOfBatch && (
				<div className="pt-1 text-xs text-muted-foreground">
					Part of a Behavior run — approve or reject it from the run's change-set
					above.
				</div>
			)}

			{/* Approve / Reject buttons — hidden for batch-window proposals (the
			    change-set card owns that decision). */}
			{isPending && runId && !resolved && !partOfBatch && (
				<div className="flex items-center gap-2 pt-1">
					{!showRejectInput ? (
						<>
							<Button
								size="sm"
								className="h-7 text-xs"
								onClick={() =>
									approveRun.mutate(
										{ run_id: runId, input: formValues },
										{
											// The permalink already carries the pending event id, and
											// the server now resolves that id to the whole supersede
											// chain (pending→executing→completed). No URL rewrite —
											// rewriting to the executing event_id only re-staled the
											// link when the device completed.
											onSuccess: () => {
												setResolved("confirmed");
											},
										},
									)
								}
								disabled={approveRun.isPending || rejectRun.isPending}
							>
								{approveRun.isPending ? (
									<Spinner size="sm" className="mr-1" />
								) : (
									<Check className="h-3 w-3 mr-1" />
								)}
								Confirm
							</Button>
							<Button
								size="sm"
								variant="outline"
								className="h-7 text-xs"
								onClick={() => setShowRejectInput(true)}
								disabled={approveRun.isPending || rejectRun.isPending}
							>
								<X className="h-3 w-3 mr-1" />
								Reject
							</Button>
						</>
					) : (
						<div className="flex items-center gap-2 w-full">
							<input
								type="text"
								placeholder="Reason (optional)"
								value={rejectReason}
								onChange={(e) => setRejectReason(e.target.value)}
								className="h-7 text-xs border rounded px-2 flex-1 bg-background"
							/>
							<Button
								size="sm"
								variant="destructive"
								className="h-7 text-xs"
								onClick={() =>
									rejectRun.mutate(
										{ run_id: runId, reason: rejectReason || undefined },
										{
											// See the confirm handler above: the original permalink
											// now resolves to the full chain server-side, so no URL
											// rewrite is needed here either.
											onSuccess: () => {
												setResolved("rejected");
											},
										},
									)
								}
								disabled={rejectRun.isPending}
							>
								{rejectRun.isPending && <Spinner size="sm" className="mr-1" />}
								Confirm Reject
							</Button>
							<Button
								size="sm"
								variant="ghost"
								className="h-7 text-xs px-2"
								onClick={() => {
									setShowRejectInput(false);
									setRejectReason("");
								}}
							>
								Cancel
							</Button>
						</div>
					)}
				</div>
			)}
		</div>
	);
}

type ChangeSetEntry = {
	entityId: number;
	name: string;
	kind: "created" | "updated";
	applied: Record<string, { old: unknown; new: unknown }>;
};

/**
 * A watcher run's first-class change-set card: the created/updated summary and a
 * per-entity diff, shown on the run itself even when the changes were auto-applied
 * (no approval). When the run has a window and produced pending proposals, offers
 * a one-click Approve all / Reject with feedback (the batch + revision loop —
 * rejecting feeds the reason back so the user can ask the agent to revise). The
 * batch-reject feedback event renders the recorded reason instead.
 */
function RunChangeSetCard({ content }: { content: ContentItem }) {
	const metadata = (content.metadata || {}) as Record<string, unknown>;
	const kind = metadata.kind as string | undefined;
	const windowId =
		typeof metadata.window_id === "number" ? metadata.window_id : null;
	const watcherId =
		typeof metadata.window_id === "number" &&
		typeof metadata.watcher_id === "number"
			? metadata.watcher_id
			: typeof metadata.watcher_id === "number"
				? metadata.watcher_id
				: null;
	const { org } = useCurrentOrg();
	const ownerSlug = org?.slug;
	// Resolve the watcher so the card can name it (and link to its page) — a batch
	// card with no identity is impossible to tell apart from another run's card.
	const watcherDetail = useWatcherDetail(
		watcherId != null ? String(watcherId) : undefined,
		undefined,
		org?.id,
		{ includeVersions: false },
	);
	const watcher = watcherDetail.data?.behavior;
	const watcherName =
		watcher?.behavior_name ??
		(watcherId != null ? `Behavior ${watcherId}` : "A Behavior");
	const watcherAgentId = watcher?.agent_id ?? null;
	const approveBatch = useApproveBatch();
	const rejectBatch = useRejectBatch();
	const [showReject, setShowReject] = useState(false);
	const [reason, setReason] = useState("");
	const [resolved, setResolved] = useState<"approved" | "rejected" | null>(
		null,
	);

	// The batch-reject feedback record: show why the run's proposals were rejected.
	if (kind === "watcher_batch_reject") {
		const rejectReason = (metadata.reason as string | undefined) || undefined;
		return (
			<div className="rounded-md border border-destructive/40 bg-destructive/5 p-3">
				<div className="text-sm font-medium">Proposals rejected</div>
				{rejectReason && (
					<div className="mt-1 text-sm text-muted-foreground">
						{rejectReason}
					</div>
				)}
				<div className="mt-1 text-xs text-muted-foreground">
					Ask the agent to revise its proposals with this feedback.
				</div>
			</div>
		);
	}

	const changes = Array.isArray(metadata.changes)
		? (metadata.changes as ChangeSetEntry[])
		: [];
	const createdCount =
		typeof metadata.created_count === "number"
			? metadata.created_count
			: changes.filter((c) => c.kind === "created").length;
	const updatedCount =
		typeof metadata.updated_count === "number"
			? metadata.updated_count
			: changes.filter((c) => c.kind === "updated").length;
	const updatedChanges = changes.filter(
		(c) => c.kind === "updated" && Object.keys(c.applied || {}).length > 0,
	);
	// Live count of proposals still awaiting a decision for this window (stamped
	// server-side; the change_set event itself is permanent). Undefined for older
	// events without the field — treat as "show buttons" so nothing regresses.
	const pendingProposalCount =
		typeof metadata.pending_proposal_count === "number"
			? metadata.pending_proposal_count
			: null;
	// Show the batch controls only while proposals remain pending. This survives a
	// refresh (server-derived), unlike the local `resolved` state which only hides
	// them within the current session after a click.
	const hasPendingProposals =
		pendingProposalCount == null || pendingProposalCount > 0;

	// While proposals are still pending they are PROPOSED, not yet applied — say so.
	const summaryVerb = hasPendingProposals ? "proposed" : "applied";

	return (
		<div className="rounded-md border p-3">
			<div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
				<div className="text-sm font-medium">
					{summaryVerb === "proposed" ? "Proposed" : "Applied"} {createdCount}{" "}
					new + {updatedCount} updated
				</div>
				{/* Behavior identity + which run/window this card is — so cards are
				    distinguishable and a stray approve error is traceable to a run. */}
				<div className="text-xs text-muted-foreground">
					{ownerSlug && watcherAgentId && watcherId != null ? (
						<Link
							to="/$owner/agents/$agentId/behaviors/$watcherId"
							params={{
								owner: ownerSlug,
								agentId: watcherAgentId,
								watcherId: String(watcherId),
							}}
							search={{ view: "definition", run_id: undefined }}
							className="font-medium text-foreground underline-offset-4 hover:underline"
						>
							{watcherName}
						</Link>
					) : (
						<span className="font-medium text-foreground">{watcherName}</span>
					)}
					{windowId != null && <span> · run window #{windowId}</span>}
					{pendingProposalCount != null && pendingProposalCount > 0 && (
						<span> · {pendingProposalCount} pending</span>
					)}
				</div>
			</div>

			{/* Per-entity diff for updates — auto-applied changes are shown too. */}
			{updatedChanges.length > 0 && (
				<div className="mt-3 space-y-2">
					{updatedChanges.map((change) => (
						<div key={change.entityId} className="space-y-1.5">
							<div className="text-xs font-medium text-muted-foreground">
								{change.name}
							</div>
							{Object.entries(change.applied).map(([field, diff]) => (
								<FieldChangeDiff
									key={field}
									label={field}
									before={diff.old}
									after={diff.new}
								/>
							))}
						</div>
					))}
				</div>
			)}

			{/* Batch controls: approve-all / reject-with-feedback for the run's window.
			    Only while proposals remain pending (server-derived, refresh-safe) and
			    not already resolved in this session. */}
			{windowId != null && resolved == null && hasPendingProposals && (
				<div className="mt-3 border-t border-border/70 pt-3">
					{!showReject ? (
						<div className="flex items-center gap-2">
							<Button
								size="sm"
								className="h-7 text-xs"
								onClick={() =>
									approveBatch.mutate(
										{ window_id: windowId },
										{ onSuccess: () => setResolved("approved") },
									)
								}
								disabled={approveBatch.isPending || rejectBatch.isPending}
							>
								{approveBatch.isPending && (
									<Spinner size="sm" className="mr-1" />
								)}
								Approve all proposals
							</Button>
							<Button
								size="sm"
								variant="outline"
								className="h-7 text-xs"
								onClick={() => setShowReject(true)}
								disabled={approveBatch.isPending || rejectBatch.isPending}
							>
								Reject with feedback
							</Button>
						</div>
					) : (
						<div className="flex items-center gap-2 w-full">
							<input
								type="text"
								placeholder="What should the agent change?"
								value={reason}
								onChange={(e) => setReason(e.target.value)}
								className="h-7 text-xs border rounded px-2 flex-1 bg-background"
							/>
							<Button
								size="sm"
								variant="destructive"
								className="h-7 text-xs"
								onClick={() =>
									rejectBatch.mutate(
										{ window_id: windowId, reason: reason || undefined },
										{ onSuccess: () => setResolved("rejected") },
									)
								}
								disabled={rejectBatch.isPending}
							>
								{rejectBatch.isPending && (
									<Spinner size="sm" className="mr-1" />
								)}
								Reject all
							</Button>
							<Button
								size="sm"
								variant="ghost"
								className="h-7 text-xs px-2"
								onClick={() => {
									setShowReject(false);
									setReason("");
								}}
							>
								Cancel
							</Button>
						</div>
					)}
				</div>
			)}
			{resolved === "approved" && (
				<div className="mt-3 text-xs text-muted-foreground">
					All proposals approved.
				</div>
			)}
			{resolved === "rejected" && (
				<div className="mt-3 text-xs text-muted-foreground">
					Proposals rejected — ask the agent to revise them.
				</div>
			)}
			{/* Reviewed in a PRIOR session (server says no proposals remain pending):
			    show a resolved marker instead of nothing, so the card reads as done. */}
			{windowId != null && resolved == null && !hasPendingProposals && (
				<div className="mt-3 text-xs text-muted-foreground">
					All proposals reviewed.
				</div>
			)}
		</div>
	);
}

