216				{iconElement ?? <Icon className="h-12 w-12 mb-4 opacity-50" />}
217				<p className="text-lg font-medium">{title}</p>
218				<p className="text-sm mt-1">{description}</p>
219				{children}
220				{(hasPrimary || hasSecondary) && (
221					<div className="mt-4 flex flex-wrap items-center justify-center gap-2">
222						{hasPrimary && (
223							<Button variant="default" onClick={onAction}>
224								<Plus className="mr-2 h-4 w-4" />
225								{actionLabel}
226							</Button>
227						)}
228						{hasSecondary &&
229							(secondaryActionTo ? (
230								<Button asChild variant="outline">
231									<Link to={secondaryActionTo as "/"}>
232										{secondaryActionLabel}
233									</Link>
234								</Button>
235							) : (
236								<Button variant="outline" onClick={secondaryOnAction}>
237									{secondaryActionLabel}
238								</Button>
239							))}
240					</div>
241				)}
242			</div>
243		);
244	}
