					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton blocks
						key={i}
						className="space-y-3 rounded-lg border p-4"
					>
						<Skeleton className="h-4 w-1/3" />
						<div className="space-y-2">
							<Skeleton className="h-3 w-full" />
							<Skeleton className="h-3 w-5/6" />
							<Skeleton className="h-3 w-3/4" />
						</div>
					</div>
				))}
			</div>
		);
	}

	if (variant === "panel") {
		return (
			<div
				role="status"
				aria-label={`Loading ${label}`}
				className={cn("space-y-3", className)}
			>
				<Skeleton className="h-5 w-1/4" />
				<Skeleton className="h-3 w-full" />
				<Skeleton className="h-3 w-5/6" />
				<Skeleton className="h-3 w-2/3" />
			</div>
		);
	}

	return (
		<div
			role="status"
			aria-label={`Loading ${label}`}
			className={cn("rounded-lg border", className)}
		>
			<div className="border-b px-4 py-3">
				<Skeleton className="h-3 w-1/4" />
			</div>
			<div className="divide-y">
				{Array.from({ length: rows }).map((_, i) => (
					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
						key={i}
						className="flex items-center gap-3 px-4 py-3"
					>
						<Skeleton
							className="h-3 flex-1"
							style={{ maxWidth: `${50 + ((i * 17) % 30)}%` }}
						/>
						<Skeleton className="ml-auto h-3 w-16 shrink-0" />
					</div>
				))}
			</div>
		</div>
	);
}

/** Router default pending shell — panel-shaped, not the table `rows` variant. */
export function PageRoutePendingShell() {
	return (
		<div className="px-4 py-6 lg:px-6">
			<TabLoadingState label="page" variant="panel" />
		</div>
	);
}

export function TabErrorState({ label }: { label: string }) {
	return (
		<div className="flex items-center justify-center py-12 text-destructive">
			<AlertCircle className="mr-2 h-4 w-4" />
			Failed to load {label}
		</div>
	);
}

export function TabEmptyState({
	icon: Icon,
	title,
	description,
	actionLabel,
	onAction,
	// Optional secondary action — rendered as a quieter button beside the
	// primary one. `secondaryActionTo` makes it a router link; otherwise pass
	// `secondaryOnAction`. Used e.g. on the agents empty state ("Create agent"
	// + "Link your agent").
	secondaryActionLabel,
	secondaryActionTo,
	secondaryOnAction,
	iconElement,
	children,
}: {
	icon: LucideIcon;
	title: string;
	description: string;
	actionLabel?: string;
	onAction?: () => void;
	secondaryActionLabel?: string;
	secondaryActionTo?: string;
	secondaryOnAction?: () => void;
	iconElement?: ReactNode;
	children?: ReactNode;
}) {
	const hasPrimary = Boolean(actionLabel && onAction);
	const hasSecondary = Boolean(
		secondaryActionLabel && (secondaryActionTo || secondaryOnAction),
	);

	return (
		<div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
			{iconElement ?? <Icon className="h-12 w-12 mb-4 opacity-50" />}
			<p className="text-lg font-medium">{title}</p>
			<p className="text-sm mt-1">{description}</p>
			{children}
			{(hasPrimary || hasSecondary) && (
				<div className="mt-4 flex flex-wrap items-center justify-center gap-2">
					{hasPrimary && (
						<Button variant="default" onClick={onAction}>
							<Plus className="mr-2 h-4 w-4" />
							{actionLabel}
						</Button>
					)}
					{hasSecondary &&
						(secondaryActionTo ? (
							<Button asChild variant="outline">
								<Link to={secondaryActionTo as "/"}>
									{secondaryActionLabel}
								</Link>
							</Button>
						) : (
							<Button variant="outline" onClick={secondaryOnAction}>
								{secondaryActionLabel}
							</Button>
						))}
				</div>
			)}
		</div>
	);
}

