import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRouteWithContext,
	createRoute,
	createRouter,
	Outlet,
	RouterProvider,
} from "@tanstack/react-router";
import { render, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { setAuthStateMock } from "@/test/auth-state-mock";
import { server } from "@/test/msw-server";
import { EventsTab } from "./index";

/**
 * Pins the gate added in PR #49 + the bootstrap-window fix: the auth
 * `read_knowledge` POST and the public `public/knowledge/search` GET no longer
 * fan out in parallel, AND neither fires while `isReady=false`. If either
 * gate is removed, this suite fails because the "should not fire" assertions
 * see a hit during the relevant phase.
 */
describe("EventsTab auth gate", () => {
	let authPostCount: number;
	let publicGetCount: number;
	let errSpy: ReturnType<typeof vi.spyOn>;

	beforeEach(() => {
		authPostCount = 0;
		publicGetCount = 0;
		errSpy = vi.spyOn(console, "error").mockImplementation(() => {});

		server.use(
			http.post("*/api/private-org/read_knowledge", () => {
				authPostCount += 1;
				return HttpResponse.json({
					content: [],
					total: 0,
					classification_stats: {},
					page: { limit: 50, offset: 0, has_more: false },
				});
			}),
			http.get("*/api/private-org/public/knowledge/search", () => {
				publicGetCount += 1;
				return HttpResponse.json({
					content: [],
					total: 0,
					classification_stats: {},
					page: { limit: 50, offset: 0, has_more: false },
				});
			}),
		);
	});

	afterEach(() => {
		errSpy.mockRestore();
	});

	function mockOrganizationMembership(isMember: boolean) {
		server.use(
			http.get("*/api/organizations", () =>
				HttpResponse.json({
					organizations: [
						{
							id: "private-org-id",
							name: "Private Org",
							slug: "private-org",
							visibility: "public",
							is_member: isMember,
						},
					],
				}),
			),
		);
	}

	function renderWith(
		auth:
			| "authenticated"
			| "anonymous"
			| { isAuthenticated: boolean; isReady: boolean },
		initialEntries: string[] = ["/private-org"],
	) {
		if (typeof auth === "string") {
			setAuthStateMock(auth);
		} else {
			setAuthStateMock({
				isAuthenticated: auth.isAuthenticated,
				isReady: auth.isReady,
				session: null,
			});
		}
		const queryClient = new QueryClient({
			defaultOptions: {
				queries: { retry: false },
				mutations: { retry: false },
			},
		});

		const rootRoute = createRootRouteWithContext()({
			component: () => <Outlet />,
		});
		const indexRoute = createRoute({
			path: "/$owner",
			getParentRoute: () => rootRoute,
			component: () => (
				<EventsTab organizationId="private-org-id" ownerSlug="private-org" />
			),
		});
		const router = createRouter({
			routeTree: rootRoute.addChildren([indexRoute]),
			history: createMemoryHistory({ initialEntries }),
			context: { queryClient },
		});

		return render(
			<QueryClientProvider client={queryClient}>
				{/** biome-ignore lint/suspicious/noExplicitAny: typed router casted for memory variant */}
				<RouterProvider router={router as any} />
			</QueryClientProvider>,
		);
	}

	it("authenticated member: hits read_knowledge, never the public search URL", async () => {
		mockOrganizationMembership(true);
		renderWith("authenticated");
		await waitFor(() => expect(authPostCount).toBeGreaterThan(0));
		// Give the public hook a chance to mis-fire if the gate were broken.
		await new Promise((resolve) => setTimeout(resolve, 50));

		expect(authPostCount).toBeGreaterThan(0);
		expect(publicGetCount).toBe(0);
	});

	it("authenticated non-member: hits public search URL, never the auth POST", async () => {
		mockOrganizationMembership(false);
		renderWith("authenticated");
		await waitFor(() => expect(publicGetCount).toBeGreaterThan(0));
		await new Promise((resolve) => setTimeout(resolve, 50));

		expect(publicGetCount).toBeGreaterThan(0);
		expect(authPostCount).toBe(0);
	});

	it("anonymous: hits public search URL, never the auth POST", async () => {
		renderWith("anonymous");
		await waitFor(() => expect(publicGetCount).toBeGreaterThan(0));
		await new Promise((resolve) => setTimeout(resolve, 50));

		expect(publicGetCount).toBeGreaterThan(0);
		expect(authPostCount).toBe(0);
	});

	it("bootstrap (isAuthenticated=false, isReady=false): fires neither query", async () => {
		renderWith({ isAuthenticated: false, isReady: false });
		// Generous wait — if either gate is loose, the misfire happens within
		// a few microtasks of mount.
		await new Promise((resolve) => setTimeout(resolve, 100));

		expect(authPostCount).toBe(0);
		expect(publicGetCount).toBe(0);
	});

	// The entity page's "See memory" deep-links into the org-wide Memory page with
	// ?entity_id=…. This pins that the URL filter scopes the knowledge query (so
	// there are no per-entity tabs to duplicate it) and surfaces the drill-down
	// banner.
	it("scopes the knowledge query to the ?entity_id URL filter + shows the banner", async () => {
		mockOrganizationMembership(true);
		let capturedEntityId: unknown;
		server.use(
			http.post("*/api/private-org/read_knowledge", async ({ request }) => {
				const body = (await request.json()) as { entity_id?: unknown };
				capturedEntityId = body.entity_id;
				return HttpResponse.json({
					content: [],
					total: 0,
					classification_stats: {},
					page: { limit: 50, offset: 0, has_more: false },
				});
			}),
		);

		const { findByText } = renderWith("authenticated", [
			"/private-org?entity_id=62",
		]);

		await waitFor(() => expect(capturedEntityId).toBe(62));
		expect(await findByText(/Showing memory for/)).toBeTruthy();
	});

	// An empty workspace previews the feed with sample events rendered through the
	// real EventCard, so the page shows what Activity becomes rather than an
	// abstract skeleton. These assertions pin that the preview actually paints —
	// including the approval card, the branch most likely to throw on synthetic
	// data — and that the CTA is present.
	describe("empty-state feed preview", () => {
		it("renders sample events through the real card, plus the connect CTA", async () => {
			mockOrganizationMembership(true);
			const { findByText, getByText } = renderWith("authenticated");

			expect(await findByText("No activity yet")).toBeTruthy();
			expect(getByText("Connect your data")).toBeTruthy();

			// A plain message event and an email event.
			expect(
				getByText("#launch — can we get the pricing page copy today?"),
			).toBeTruthy();
			expect(
				getByText("Re: Northwind renewal — contract questions"),
			).toBeTruthy();

			// The pending approval renders its field diff (current → proposed)
			// and names the agent that requested it via the recorded initiator.
			expect(getByText("Update company field: Stage")).toBeTruthy();
			expect(getByText("Growth")).toBeTruthy();
			expect(getByText("Enterprise")).toBeTruthy();
			expect(getByText(/crm-enrichment/)).toBeTruthy();

			// A completed interaction keeps its terminal badge.
			expect(getByText("Completed")).toBeTruthy();
		});

		// The interaction cards are the point of the preview — they show that
		// Activity is where you approve work, not just a log. An earlier revision
		// buried them under the overlay and inside the fade, so pin that they lead.
		it("leads with the pending approval, then the completed action", async () => {
			mockOrganizationMembership(true);
			const { findByText, container } = renderWith("authenticated");
			await findByText("No activity yet");

			// Approval cards render their title in a <span>, plain events in an
			// <h4>, so compare document position rather than filtering by tag.
			const positionOf = (text: string) => {
				const nodes = [...container.querySelectorAll("h4, span")];
				return nodes.findIndex((n) => n.textContent?.trim() === text);
			};

			const approval = positionOf("Update company field: Stage");
			const completed = positionOf("Create issue in Support triage");
			const firstMessage = positionOf(
				"#launch — can we get the pricing page copy today?",
			);

			expect(approval).toBeGreaterThanOrEqual(0);
			expect(completed).toBeGreaterThan(approval);
			expect(firstMessage).toBeGreaterThan(completed);
		});

		it("marks the preview aria-hidden so it is not announced as real activity", async () => {
			mockOrganizationMembership(true);
			const { findByText, container } = renderWith("authenticated");
			await findByText("No activity yet");

			const preview = container.querySelector('[aria-hidden="true"]');
			expect(preview).toBeTruthy();
			expect(preview?.textContent).toContain("Northwind");
		});
	});
});

