import { createFileRoute, Link, Outlet } from "@tanstack/react-router";
import { ArrowLeft, Cable } from "lucide-react";
import { ConnectionCreate } from "@/components/entity-tabs/connections-tab/connection-create";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { Button } from "@/components/ui/button";
import { FormLoadingShell } from "@/components/ui/form-loading-shell";
import {
	useConnections,
	useInstallableConnectorCatalog,
} from "@/lib/api/connections";
import { useInferenceProviders } from "@/lib/api/inference-providers";
import { useSandboxes } from "@/lib/api/sandboxes";

// Pure layout: the actual pages live in the child routes `create/index.tsx`
// (bare /create picker) and `create.$connectorKey.tsx` (deep-linked). Rendering
// its own UI here would shadow the child, so it only hosts the <Outlet/>.
export const Route = createFileRoute("/$owner/connectors/create")({
	component: () => <Outlet />,
});

export function ConnectionsCreateRouteContent({
	owner,
	initialConnectorKey,
}: {
	owner: string;
	initialConnectorKey?: string;
}) {
	return (
		<OwnerWorkspaceGate owner={owner}>
			{(props) => (
				<ConnectionsCreateInner
					ownerSlug={props.ownerSlug}
					organizationId={props.organizationId}
					initialConnectorKey={initialConnectorKey}
				/>
			)}
		</OwnerWorkspaceGate>
	);
}

function ConnectionsCreateInner({
	ownerSlug,
	organizationId,
	initialConnectorKey,
}: {
	ownerSlug: string;
	organizationId: string | null;
	initialConnectorKey?: string;
}) {
	const { data: connections = [] } = useConnections(organizationId ?? "");
	// The connectors list redirects here when the org has nothing yet, so the
	// back arrow only renders once something exists to go back TO — otherwise
	// it would bounce straight back into the redirect.
	const { data: installedDefs = [] } = useInstallableConnectorCatalog(
		organizationId ?? "",
	);
	const { data: inferenceProviders = [] } = useInferenceProviders({
		enabled: Boolean(organizationId),
	});
	const { data: sandboxesPayload } = useSandboxes({
		enabled: Boolean(organizationId),
	});
	const hasConnectorInventory =
		connections.length > 0 ||
		installedDefs.some((def) => def.installed) ||
		inferenceProviders.length > 0 ||
		(sandboxesPayload?.sandboxes.length ?? 0) > 0;
	// Page padding comes from the connectors layout.
	return (
		<div className="flex w-full max-w-3xl flex-1 flex-col gap-6">
			<div className="space-y-1">
				<div className="flex items-center gap-2">
					{hasConnectorInventory ? (
						<Button
							asChild
							variant="ghost"
							size="icon"
							className="h-8 w-8 shrink-0"
						>
							<Link
								to="/$owner/connectors"
								params={{ owner: ownerSlug }}
								search={{}}
								aria-label="Back to connectors"
							>
								<ArrowLeft className="h-4 w-4" />
							</Link>
						</Button>
					) : null}
					<Cable className="h-6 w-6" />
					<h1 className="text-2xl font-semibold leading-tight">
						Add a connection
					</h1>
				</div>
				<p className="text-sm text-muted-foreground">
					Pick a connector from the catalog or drop in an MCP URL — Lobu handles
					auth and brings the data into memory.
				</p>
			</div>
			{/* Form body renders a label+input skeleton while workspace is
			 *  in flight (ConnectionCreate's connector picker depends on
			 *  orgId). Page chrome above paints from frame one regardless. */}
			{organizationId ? (
				<ConnectionCreate
					ownerSlug={ownerSlug}
					organizationId={organizationId}
					connections={connections}
					initialConnectorKey={initialConnectorKey}
				/>
			) : (
				<div className="max-w-3xl">
					<FormLoadingShell rows={4} />
				</div>
			)}
		</div>
	);
}

