// @vitest-environment jsdom
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

/**
 * Covers the Configure tab strip that replaced the per-agent sidebar rows:
 * which tabs exist, that Permissions is admin-only, and that Models and
 * Settings are genuinely separate surfaces rather than one page.
 */

vi.mock("@tanstack/react-router", async () => {
	const actual = await vi.importActual<
		typeof import("@tanstack/react-router")
	>("@tanstack/react-router");
	return {
		...actual,
		useNavigate: () => vi.fn(),
		useLocation: () => ({ pathname: mockPathname.value }),
		Link: ({
			children,
			to,
			params,
			...rest
		}: {
			children: React.ReactNode;
			to: string;
			params?: Record<string, string>;
		} & Record<string, unknown>) => {
			const href = Object.entries(params ?? {}).reduce(
				(acc, [key, value]) => acc.replace(`$${key}`, value),
				to,
			);
			return (
				<a href={href} {...rest}>
					{children}
				</a>
			);
		},
	};
});

const mockPathname = { value: "/acme/agents/bot/models" };
const membership = { isAdmin: true, isLoading: false };

vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ orgContext: { organizationId: "org-1" } }),
}));
vi.mock("@/hooks/use-members", () => ({ useMembers: () => membership }));
vi.mock("@/hooks/use-current-org", () => ({
	useCurrentOrg: () => ({ isMember: true, isLoading: false, org: null }),
}));
vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ isAuthenticated: true, isReady: true }),
}));
vi.mock("@/lib/api", () => ({
	useAgents: () => ({
		data: [{ agentId: "bot", name: "Bot" }],
		isLoading: false,
	}),
}));

import { AgentsWorkbenchLayout } from "./agents-workbench";

function tabNames(): string[] {
	return screen
		.getAllByRole("link")
		.map((link) => link.textContent?.trim() ?? "");
}

describe("Configure tab strip", () => {
	afterEach(() => {
		cleanup();
		membership.isAdmin = true;
		mockPathname.value = "/acme/agents/bot/models";
	});

	it("exposes the five config surfaces to an admin", () => {
		render(<AgentsWorkbenchLayout owner="acme" agentId="bot" />);
		const names = tabNames();
		for (const label of [
			"Skills",
			"Guardrails",
			"Permissions",
			"Models",
			"Settings",
		]) {
			expect(names).toContain(label);
		}
	});

	// Permissions reads/writes the org write-gate envelope, which needs org
	// settings admin — a member landing there would only get a 403.
	it("hides Permissions from non-admin members", () => {
		membership.isAdmin = false;
		render(<AgentsWorkbenchLayout owner="acme" agentId="bot" />);
		const names = tabNames();
		expect(names).not.toContain("Permissions");
		expect(names).toContain("Skills");
		expect(names).toContain("Models");
	});

	// Models moved out of Settings; they must be distinct destinations, or the
	// split this branch performs is cosmetic.
	it("points Models and Settings at separate routes", () => {
		render(<AgentsWorkbenchLayout owner="acme" agentId="bot" />);
		const links = screen.getAllByRole("link");
		const href = (label: string) =>
			links.find((l) => l.textContent?.trim() === label)?.getAttribute("href");

		expect(href("Models")).toBe("/acme/agents/bot/models");
		expect(href("Settings")).toBe("/acme/agents/bot/settings");
	});

	// Chat and Behaviors keep their own sidebar rows — folding them into the
	// strip would duplicate navigation the sidebar already owns.
	it("keeps Chat and Behaviors out of the config strip", () => {
		render(<AgentsWorkbenchLayout owner="acme" agentId="bot" />);
		const names = tabNames();
		expect(names).not.toContain("Behaviors");
		expect(names).not.toContain("Chat");
	});
});

