  const { routeTree } = await import('@/routeTree.gen');

  const history = createMemoryHistory({ initialEntries: [path] });
  const router = createRouter({
    routeTree,
    history,
    context: { queryClient },
    // Search-param parsing in the real router uses the URL form — keep defaults
    // so `validateSearch` on each route runs against an empty object.
    defaultPreload: false,
    // Mirror the real router (src/router.ts) so smokes of deleted legacy
    // paths exercise the same not-found surface production serves.
    defaultNotFoundComponent: GlobalNotFound,
  });

  const ui: ReactNode = (
    <QueryClientProvider client={queryClient}>
      {/** biome-ignore lint/suspicious/noExplicitAny: typed router casted for memory variant */}
      <RouterProvider router={router as any} />
    </QueryClientProvider>
  );

  const result = render(ui);
  return { ...result, queryClient };
}
