// @vitest-environment jsdom
import { screen, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { afterEach, describe, expect, it, vi } from "vitest";

/**
 * Covers the Configure tab strip that replaced the per-agent sidebar rows:
 * which tabs exist, that Permissions is admin-only, and that Models and
 * Settings are genuinely separate destinations rather than one page.
 *
 * Driven through the real router so the strip is exercised the way a user
 * reaches it, rather than by hand-assembling its provider tree.
 */

const membership = { isAdmin: true, isLoading: false };
vi.mock("@/hooks/use-members", () => ({ useMembers: () => membership }));

import { renderRoute } from "@/test/render";

const OWNER = "test-org";
const AGENT = "agent-a";

const agentHandlers = [
	http.get("*/api/organizations", () =>
		HttpResponse.json({
			organizations: [
				{
					id: "org-1",
					name: "Test Org",
					slug: OWNER,
					visibility: "private",
					is_member: true,
				},
			],
		}),
	),
];

/** Visible labels of the config strip's links. */
async function tabNames(): Promise<string[]> {
	await waitFor(() => expect(screen.getAllByRole("link").length).toBeGreaterThan(0));
	return screen.getAllByRole("link").map((l) => l.textContent?.trim() ?? "");
}

describe("Configure tab strip", () => {
	afterEach(() => {
		membership.isAdmin = true;
	});

	it("exposes the five config surfaces to an admin", async () => {
		await renderRoute(`/${OWNER}/agents/${AGENT}/models`, {
			authenticated: true,
			extraHandlers: agentHandlers,
		});

		const names = await tabNames();
		for (const label of [
			"Skills",
			"Guardrails",
			"Permissions",
			"Models",
			"Settings",
		]) {
			expect(names).toContain(label);
		}
	});

	// Permissions reads/writes the org write-gate envelope, which requires org
	// settings admin — a regular member landing there would only get a 403.
	it("hides Permissions from non-admin members", async () => {
		membership.isAdmin = false;
		await renderRoute(`/${OWNER}/agents/${AGENT}/models`, {
			authenticated: true,
			extraHandlers: agentHandlers,
		});

		const names = await tabNames();
		expect(names).not.toContain("Permissions");
		expect(names).toContain("Skills");
		expect(names).toContain("Models");
	});

	// Models moved out of Settings; they must be distinct destinations or the
	// split this branch performs is cosmetic.
	it("points Models and Settings at separate routes", async () => {
		await renderRoute(`/${OWNER}/agents/${AGENT}/models`, {
			authenticated: true,
			extraHandlers: agentHandlers,
		});
		await tabNames();

		const links = screen.getAllByRole("link");
		const href = (label: string) =>
			links.find((l) => l.textContent?.trim() === label)?.getAttribute("href");

		expect(href("Models")).toBe(`/${OWNER}/agents/${AGENT}/models`);
		expect(href("Settings")).toBe(`/${OWNER}/agents/${AGENT}/settings`);
	});
});

